test('file classes are walked in LIST order — the list is the user\'s statement of intent', () => {
  // v1.46.68.0 ranked catch-all ('*' / empty) filename patterns after specific
  // ones, on the theory that a wildcard should never shadow a named file. Taken
  // back out: a user who puts the catch-all at the bottom has already said where
  // it goes, and a rule that quietly re-sorts their list is a second opinion
  // they did not ask for. Order is order. Reported 2026-08-27.
  const bytes = s => { const b = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i); return b; };
  const file = (name, label, pattern) => ({
    name, label, kind: 'file', recognizers: [{ type: 'filename', pattern }],
    ddl_bindings: ['V/S/D/REC'], parse_spec_binary: [{ 'read-ddl': {} }] });
  const specific = () => file('CPF', 'CPF file', '$VOL1.SUBVOL.CPF');
  const anyFile  = () => file('FILE', 'Any file', '*');

  domEl._fmtSave([specific(), anyFile()]);
  domEl._fmtLoad();
  eq(domEl._fmtDetect(bytes('DATA'), { filename: '$VOL1.SUBVOL.CPF' })?.label, 'CPF file',
     'the catch-all was left LAST — the class above it must win');
  eq(domEl._fmtDetect(bytes('DATA'), { filename: '$VOL1.SUBVOL.OTHER' })?.label, 'Any file',
     'and it still catches what nothing above it claims');

  // The reverse order is the user saying the opposite, and it is honoured too.
  domEl._fmtSave([anyFile(), specific()]);
  domEl._fmtLoad();
  eq(domEl._fmtDetect(bytes('DATA'), { filename: '$VOL1.SUBVOL.CPF' })?.label, 'Any file',
     'a catch-all placed FIRST is a deliberate catch-all — do not re-sort the list');

  // Nothing may reintroduce a specificity bucket.
  const fn = (fs.readFileSync('./source.html', 'utf8').match(/function _detectOrderIdxs[\s\S]*?\n  \}/) || [''])[0];
  assert.ok(/return msgs\.concat\(other, files\);/.test(fn), 'the file group is one bucket, in list order');

  storage.removeItem('up_format_specs');
  domEl._fmtLoad();
});

test('[REGRESSION] the Files list shows the order detection actually uses', () => {
  // The Files list sorted itself alphabetically for display while detection
  // walked the stored array — so a catch-all '*' class sitting FIRST in the
  // array rendered LAST (S after C) and swallowed every file record, while the
  // list on screen said the specific class came first. Hours were spent on
  // "you are not following the order": the app wasn't, and the list said
  // otherwise. Reported 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  const fn  = psFnSource('_meRenderSpecList');
  assert.ok(!/localeCompare/.test(fn),
    'the Files list must not re-sort what detection walks in array order');
  assert.ok(!/idxs\.sort/.test(fn), 'no display-only ordering of any list');

  // And the order must be changeable where it is shown: dropping a file row
  // inside the Files list REORDERS it, rather than only flipping its kind.
  const drop = psFnSource('_meSpecDrop');
  assert.ok(!/only reclassifies — files are unordered/.test(drop),
    'dropping inside Files still refuses to reorder');
  assert.ok(/const tgtKind = _meKindOf\(_meState\.specs\[targetIdx\]\)/.test(drop),
    'the row dropped ON decides the list — all three of them, not just Messages');
  assert.ok(/if \(tgtKind === 'msg'\) delete moved\.kind; else moved\.kind = tgtKind;/.test(drop),
    'a class dropped on Data or Files must BECOME one, not be rewritten as a message');
  assert.ok(/_meState\.specs\.splice\(dst, 0, moved\)/.test(drop), 'the move must reach the array');
});

test('imported classes carry a NEW / OVERWRITTEN badge until the list is saved', () => {
  // An import drops classes into a list you already know. The ones that landed
  // are exactly the ones to check against the original, so the rows say which
  // they are — and saving is the user signing off, which clears them.
  // Requested 2026-08-27.
  const marks = sandbox._meMarkImported, mark = sandbox._meImportMark, clear = sandbox._meClearImportMarks;
  assert.ok(typeof marks === 'function' && typeof mark === 'function', 'the marks are not reachable');
  clear();
  const a = { name: 'A', label: 'Class A' }, b = { name: 'B', label: 'Class B' };
  eq(mark(a), null, 'a class nobody imported must not be badged');
  marks(a, 'over'); marks(b, 'new');
  eq(mark(a), 'over', 'an overwritten class must say so');
  eq(mark(b), 'new', 'a new one must say so');
  // Keyed by _specKey — type code AND label, the same key the import matches on
  // — so the badge follows the class the import wrote, not whichever row happens
  // to sit at that index.
  eq(mark({ name: 'A', label: 'Class A' }), 'over', 'the mark must key on the same thing the import does');
  eq(mark({ name: 'A', label: 'Class A renamed' }), null, 'a different class must not inherit the badge');
  clear();
  eq(mark(a), null, 'clearing must actually clear');

  // Saving the Class Editor drops them.
  const save = psFnSource('_meSave');
  assert.ok(/_meImportMarks = new Map\(\);/.test(save),
    'saving the list must clear the import badges — the badge means "not looked at yet"');
  // Clearing the marks is invisible unless the list is redrawn: nothing else in
  // _meSave repaints the sidebar, so the badges sat there until some other
  // action happened to redraw. Reported 2026-08-27.
  assert.ok(/_meImportMarks\.size\) \{ _meImportMarks = new Map\(\); _meRenderSidebar\(\); \}/.test(save),
    'Save clears the marks but never repaints, so the badges stay on screen');
  // And the row renders them — on the FIRST line, beside the type code, because
  // it is a fact about the class itself and not one of the configuration notes
  // on the line below.
  const fn = psFnSource('_meRenderSpecList');
  assert.ok(/const _imp = _meImportMark\(s\)/.test(fn), 'the row never asks whether it was imported');
  assert.ok(/_imp === 'new' \? 'NEW' : 'OVERWRITTEN'/.test(fn), 'the badge text is not the two words asked for');
  assert.ok(/title\.append\(b\);/.test(fn), 'the badge belongs on the title line, not among the gap chips');
  assert.ok(fn.indexOf('title.append(b);') < fn.indexOf('const _gaps = _meItemNotes(s);'),
    'the badge must be built with the title, before the gaps line');
  // The overwrite badge speaks with the same colour the import dialog used to
  // warn about that overwrite.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.me-imp-over\{background:color-mix\(in srgb, var\(--accent2\) 16%, transparent\);\s*\n?\s*color:var\(--accent2\);border-color:var\(--accent2\);\}/.test(src),
    'the OVERWRITTEN badge must use --accent2, the colour the import dialog says "overwrite" in');
});

test('the pickers stop looking like a row of checkboxes', () => {
  // The 📋 sat immediately right of the real checkbox and read as a second one.
  // A class already has an identity here — its colour — so the row wears that.
  // And the export had TWO toggles for the two directions of one idea (keep a
  // class and its DDLs together), which left the obvious question of why anyone
  // would want one without the other. Reported 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(!/📋 \$\{esc\(nm\)\}/.test(src), 'a picker row still leads with the clipboard emoji');
  eq((src.match(/class="pick-swatch"/g) || []).length, 2, 'both pickers show the class colour instead');

  assert.ok(!/expAutoIncludeMsgs/.test(src), 'the second auto-include toggle is still there');
  assert.ok(!/expAutoIncludeDDLs/.test(src), 'the first auto-include toggle kept its old id');
  const linked = psFnSource('_expSyncLinked');
  assert.ok(/_expSyncAutoIncludeFromMsgs\(\);[\s\S]*_expSyncAutoIncludeFromDDLs\(\);/.test(linked),
    'one toggle must drive BOTH directions, or it is the old pair with a new label');
  for (const fn of ['_expSyncAutoIncludeFromMsgs', '_expSyncAutoIncludeFromDDLs'])
    assert.ok(/getElementById\('expLinkRefs'\)/.test(psFnSource(fn)),
      `${fn} still reads its own retired checkbox`);
});

test('a picker row reads as picked or not, and names look like names', () => {
  // A DDL name is the same kind of thing as a class's type code — the name of
  // the item being picked — so it takes the same colour. And the picked rows
  // are the statement the dialog is making: the unpicked ones step back, so
  // what will actually be imported reads at a glance rather than by
  // checkbox-hunting. Requested 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.pick-ddl > label \{ color: var\(--text-dim\)/.test(src),
    'a DDL name must read like a class LABEL — grey until picked');
  assert.ok(/\.pick-row > input:checked \+ label,\s*\n\s*\.pick-row > input:checked \+ label \.pick-lbl \{ color: var\(--text\); \}/.test(src),
    'picking a row must brighten its name');
  // The type code is an identifier, not a selection state — it stays accent in
  // both, and nothing may restate it per state.
  assert.ok(!/input:checked \+ label \.pick-code/.test(src),
    'the type code must not change colour with the checkbox');
});

test('identifiers stay accent and dim when nothing under them is picked', () => {
  // A type code, a volume and a subvolume are identifiers — they keep their
  // colour in every state. What changes is loudness: an identifier for
  // something you are NOT importing must not read as loud as one you are.
  // A volume/subvolume counts as picked when ANY DDL under it is, which is
  // exactly when _syncImportParents leaves it checked or indeterminate.
  // Requested 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.pick-sv   \{ padding-left: 18px; color: var\(--accent\); \}/.test(src),
    'a subvolume is the same kind of row as a volume, one level down — not a warning');
  assert.ok(/\.pick-row > input:not\(:checked\) \+ label \.pick-code,/.test(src),
    'an unpicked type code must dim');
  assert.ok(/\.pick-vol > input:not\(:checked\):not\(:indeterminate\) \+ label,/.test(src),
    'a volume with SOME children picked must not read as unpicked');
  assert.ok(/\.pick-sv  > input:not\(:checked\):not\(:indeterminate\) \+ label \{ opacity: 0\.45; \}/.test(src),
    'the subvolume must follow the same rule as the volume');
  // The indeterminate state is what makes "some children picked" visible, so the
  // parent sync has to run when the preview opens, not only on the first click.
  assert.ok(/cb\.checked = n > 0; cb\.indeterminate = n > 0 && n < ddls\.length;/.test(
    psFnSource('_syncImportParents')), 'partial selection is not expressed as indeterminate');
});

test('Track mode picks records; leaving it narrows Parse Results to them', () => {
  // Clicking a Track row used to JUMP to that record — which meant leaving Track
  // to see what you jumped to, and the table snapping back to row 1 on the way.
  // Picking is the gesture now: pick the interesting records, leave Track, and
  // Parse Results shows those and only those. Requested 2026-08-28.
  const src = fs.readFileSync('./source.html', 'utf8');
  const render = psFnSource('renderTracking');
  assert.ok(/onclick="trackPickRow\(\$\{idx\}\)"/.test(render), 'a Track row must pick, not jump');
  assert.ok(!/onclick="jumpTo\(\$\{idx\}\)"/.test(render), 'the jump-on-click is still wired');
  assert.ok(/S\.trackPicked\.has\(idx\) \? ' trk-picked' : ''/.test(render), 'a picked row must look picked');
  assert.ok(/--row-gutter:\$\{esc\(msg\.msgType\.color\)\}/.test(render),
    'the gutter is the message type colour, as in the audit list');
  assert.ok(/\.track-tbl tbody tr\.trk-picked \{ background: var\(--row-viewed\)/.test(src),
    'picked rows must wear the same ground the audit list uses');
  // The current-record tint paints the CELLS with !important, so a picked row
  // that is also the current one lost its ground and read as unpicked.
  assert.ok(/\.track-tbl tr\.trk-picked td \{ background: var\(--row-viewed\) !important; \}/.test(src),
    'picked must win over the current-row tint, or the row you are on looks unpicked');

  const pick = psFnSource('trackPickRow');
  assert.ok(/if \(S\.trackPicked\.has\(idx\)\) S\.trackPicked\.delete\(idx\); else S\.trackPicked\.add\(idx\);/.test(pick),
    'clicking must TOGGLE, or a mis-click cannot be taken back');
  // Picking record 120 of 200 rebuilt the table and lost its scroll position,
  // bouncing the list to row 1 under a mouse about to click row 121.
  // Reported 2026-08-28.
  assert.ok(/row\.classList\.toggle\('trk-picked', S\.trackPicked\.has\(idx\)\)/.test(pick),
    'a pick must toggle the row in place, not rebuild the table');
  assert.ok(/data-idx="\$\{idx\}"/.test(render), 'the row needs an id to be found by');
  // …and a rebuild for any other reason comes back where it was.
  const rt = psFnSource('renderTracking');
  assert.ok(/const _scrollTop = document\.querySelector\('\.track-tbl-wrap'\)\?\.scrollTop \|\| 0;/.test(rt),
    'a rebuild that lands somewhere else is one the user has to undo by scrolling');
  assert.ok(/wrap\.scrollTop = _scrollTop;/.test(rt), 'and it must be put back');

  // Leaving Track applies the picks, and the walk follows them in record order.
  assert.ok(/_trackApplyFilter\(\);/.test(psFnSource('toggleTrackMode')),
    'leaving Track must apply what was picked');
  const apply = psFnSource('_trackApplyFilter');
  assert.ok(/\[\.\.\.S\.trackPicked\]\.sort\(\(a, b\) => a - b\)/.test(apply),
    'the collection is walked in record order, not click order');
  assert.ok(/if \(S\.viewFilter && !S\.viewFilter\.includes\(S\.curIdx\)\)/.test(apply),
    'landing outside the selection would show a record the filter says is hidden');
  // updateNav owns the counter AND the badge — applying the filter without it
  // left "1 / 5" standing over a view holding two records. Found in the preview.
  assert.ok(/updateNav\(\);/.test(apply), 'applying the filter must redraw the counter');

  // One step function, so ‹ and › cannot disagree about what "next" means.
  const step = psFnSource('_viewStep');
  assert.ok(/S\.curIdx = S\.viewFilter\[to\];/.test(step), 'the arrows must walk the selection');
  assert.ok(/_auditLazyParseNext\(\)/.test(step), 'and still pull lazily-parsed records when unfiltered');
  for (const fn of ['prevMsg', 'nextMsg'])
    assert.ok(/_viewStep\([-+]1\)/.test(psFnSource(fn)), `${fn} must go through the one step function`);

  // The filter says so on screen and offers its own way out — but it does NOT
  // repeat the navigator's count beside it, which reads as a contradiction.
  // It reads as one sentence across the navigator: Filtered ‹ 1 / 2 › View all.
  assert.ok(/id="resFilterLabel"[^>]*>Filtered<\/span>\s*\n\s*<div id="msgNav"/.test(src),
    'the word must sit in FRONT of the count it qualifies');
  assert.ok(/<\/div>\s*\n\s*<button class="btn" id="resViewAllBtn"/.test(src),
    'and the way out after it');
  assert.ok(/<\/div>\s*\n\s*<button class="btn" id="resViewAllBtn" onclick="clearViewFilter\(\)"/.test(src),
    'the way out goes after the navigator');
  const sync = psFnSource('_syncViewFilterBar');
  assert.ok(!/textContent/.test(sync), 'the label must not carry a second copy of the count');
  // The count, the label, the navigator and View all travel as ONE group, so the
  // meta row's wrap cannot strand half of them on the left: a margin-left:auto
  // on each piece only pushes while they share a line with something else.
  // Reported 2026-08-28.
  assert.ok(!/marginLeft/.test(sync), 'spacing belongs to the group, not to a per-piece push');
  assert.ok(/\.rec-nav-group \{ display: flex; align-items: center; gap: 6px; flex-shrink: 0; margin-left: auto; \}/.test(src),
    'the record controls must be one right-aligned group');
  assert.ok(/<span id="recNavGroup" class="rec-nav-group">[\s\S]{0,900}<\/span>/.test(src),
    'the group must actually contain them');

  // Track mode is a table of many records, so the controls that act on ONE
  // record's field table — and the meta line describing it — are hidden.
  assert.ok(/body\.track-mode #resCfgControls,\s*\nbody\.track-mode #recMetaContent \{ display: none !important; \}/.test(src),
    'the per-record controls must not sit over a table of many records');
  assert.ok(/document\.body\.classList\.toggle\('track-mode', S\.trackMode\);/.test(psFnSource('toggleTrackMode')),
    'entering and leaving Track must flip the panel into and out of that mode');

  // And the count of what has been picked sits where the picking happens.
  const cnt = psFnSource('_syncTrackSelCount');
  // Beside the navigator, which already says how many records there are — the
  // count states only what is new. Requested 2026-08-28.
  assert.ok(/`\$\{n\} selected`/.test(cnt),
    'the count must say how many are picked, not repeat the total beside it');
  const src2 = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/<span id="trkSelCount"[^>]*><\/span>\s*\n\s*<span id="resFilterLabel"/.test(src2),
    'the count belongs with the other record controls');
  assert.ok(/el\.style\.display = \(S\.trackMode && n\) \? 'inline-block' : 'none';/.test(cnt),
    'the count belongs to Track mode alone, and only once something is picked');
  const clear = psFnSource('clearViewFilter');
  assert.ok(/S\.viewFilter = null;\s*\n\s*S\.trackPicked = new Set\(\);/.test(clear),
    'View all must clear the picks too, or the next exit from Track re-applies them');

  // And a selection must never outlive the messages it points at: the indices
  // would land on whatever the next parse put in those slots.
  eq((src.match(/S\.trackedFields = new Set\(\); S\.trackPicked = new Set\(\); S\.viewFilter = null;/g) || []).length, 5,
     'every place that resets tracking must reset the selection with it');
  eq((src.match(/trackMode: false, trackedFields: new Set\(\), trackPicked: new Set\(\), viewFilter: null \}/g) || []).length, 2,
     'including the two that reset state as an object literal');
});

test('[REGRESSION] the audit dump toggle names the charset it returns to', () => {
  // The preview decodes an EBCDIC payload as EBCDIC (v1.46.5x), but the toggle
  // still read ASCII while in hex — promising a view the app does not produce.
  // Reported 2026-08-28.
  // psFnSource runs to the next top-level function, which here is the sync
  // helper and then the toggle itself — bound it to this function's own body.
  const labelAll = psFnSource('_auditToggleLabel');
  // …and strip comments: the note explaining WHY it does not read _inspectBuf
  // contains the word, and the assertion is about what the code does.
  const label = labelAll.slice(0, labelAll.indexOf('\n}\n') + 3)
    .replace(/^\s*\/\/.*$/gm, '');
  assert.ok(/if \(_auditPopupMode === 'ascii'\) return 'HEX';/.test(label),
    'from the character view the toggle goes to hex, whatever the charset');
  assert.ok(/_auditDumpCharset === 'ebcdic' \? 'EBCDIC' : 'ASCII'/.test(label),
    'coming back from hex it must name the charset the record is actually shown in');
  // Read from the dump that was drawn, not re-derived: the record body arrives
  // asynchronously, so deciding at click time reads an empty buffer and every
  // record answers ASCII. Found while verifying this fix.
  assert.ok(!/_inspectBuf/.test(label),
    'the label must not re-derive the charset from a buffer that may not be loaded yet');
  assert.ok(/_auditDumpCharset = isEbcdic \? 'ebcdic' : 'ascii';/.test(psFnSource('_auditApplyDump')),
    'the dump must record the charset it rendered in');
  // The toggle is re-read when a record is drawn: the next record can be a
  // different charset, and the button would otherwise keep the last one's word.
  assert.ok(/_auditSyncDumpToggleLabel\(\)/.test(psFnSource('_auditApplyDump')),
    'moving between records must re-read the label');
  assert.ok(/_auditSyncDumpToggleLabel\(\);/.test(psFnSource('auditToggleDumpMode')),
    'clicking it must re-read the label rather than hard-coding two words');
  // Three labels now, so the width must hold the longest or the button jumps.
  const w = psFnSource('_auditSyncToggleWidth');
  assert.ok(/for \(const label of \['ASCII', 'EBCDIC', 'HEX'\]\)/.test(w),
    'the button must be measured against every label it can show');
});

test('[REGRESSION] a class row is not indented like a DDL nested under a volume', () => {
  // Class rows reused .pick-ddl for their styling, and .pick-ddl carries the
  // DDL TREE's 36px indent — the room for "volume, then subvolume, then this".
  // A class list is flat, so every row opened with an empty column.
  // Reported 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.pick-class \{ padding-left: 2px; \}/.test(src), 'the flat-row style is gone');
  eq((src.match(/class="pick-row pick-class/g) || []).length, 2,
     'both pickers must use the flat class row, not the tree row');
  assert.ok(!/pick-row pick-ddl\$\{cls\}">\s*<input type="checkbox" class="imp-spec-cb/.test(src),
    'the import CLASS row is still borrowing the tree indent');

  // .pick-vol is the TREE's volume row (bold, accent). The class's volume chip
  // took the same name and overwrote it.
  const volRow = (src.match(/\.pick-vol\s*\{[^}]*\}/g) || []);
  eq(volRow.length, 1, 'two different things are styled as .pick-vol');
  assert.ok(/font-weight: 700/.test(volRow[0]), 'the surviving .pick-vol is not the tree volume row');
  assert.ok(/class="pick-volchip"/.test(src), 'the class volume chip needs its own name');
});

test('[REGRESSION] an import is never written until its own Save is pressed', () => {
  // The rule: unsaved data is never persisted. An import used to write DDLs on
  // the spot and stage classes only when the Class Editor happened to be open,
  // so a reload kept things the user had not saved — and WHICH half survived
  // depended on whether a modal was up. Reported 2026-08-27.
  // psFnSource runs to the next TOP-LEVEL function, and the KV store below
  // confirmImport opens with a const — so slice the function by its own braces.
  const fnAll = psFnSource('confirmImport');
  // Comments say the word too ("saveTree() waits for Save"), so strip them: the
  // assertion is about what the function DOES.
  const fn = fnAll.slice(0, fnAll.indexOf('\n}\n') + 3)
    .replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
  assert.ok(!/saveTree\(\)/.test(fn), 'the import still writes the DDL tree');
  assert.ok(!/_fmtSave\(/.test(fn), 'the import still writes the class list');
  assert.ok(!/saveDeOverrides\(\)/.test(fn), 'the import still writes the DE overrides');
  // It applies to MEMORY: the pending list every reader goes through, and the
  // live tree — so the app behaves as though it happened, and a reload does not.
  assert.ok(/_fmtSetPending\(list\);/.test(fn), 'the classes must be applied to the pending list');
  assert.ok(/S\.ddlTree\[v\]\[sv\]\[d\] = tree\[v\]\[sv\]\[d\]; ddlCount\+\+;/.test(fn),
    'the DDLs must be live in memory, or nothing can be tested against them');
  // And what was saved before is kept whole, so Discard is exact.
  assert.ok(/const treeBefore  = JSON\.parse\(JSON\.stringify\(S\.ddlTree\)\);/.test(fn),
    'without the tree snapshot a discard cannot put the tree back');

  // The toast names the button AND where it lives: "press Save" only helps
  // someone who already knows there is a Save in the Class Editor, and an import
  // from the DDL tree is exactly the case where they are not looking at it.
  assert.ok(/go to Class Editor and press Save to keep it/.test(fnAll),
    'the toast must say where the Save is');

  // There is ONE Save in the app — the Class Editor's — and it commits the whole
  // bundle. Not saving IS the discard: the pending copy never reached storage,
  // so a reload comes back to the last saved state.
  const save = psFnSource('_meSave');
  assert.ok(/_fmtSave\(_meState\.specs\);/.test(save), 'the editor Save must write the classes');
  assert.ok(/if \(_pendingImport\.ddlCount\) saveTree\(\);/.test(save),
    'saving in the editor must commit the pending import\'s DDLs too');
  assert.ok(/if \(_pendingImport\.deOverrides && Object\.keys\(_pendingImport\.deOverrides\)\.length\) saveDeOverrides\(\);/.test(save),
    'and its DE overrides — the bundle commits as one thing');
});

test('the pending list is what everything reads, and it never touches storage', () => {
  // _fmtGetData is the one door to the class list, so an unsaved import is
  // expressed by putting it in front of storage rather than in it.
  // These live inside the format module's IIFE, so they are indented — psFnSource
  // only finds top-level declarations.
  const inner = name => {
    const i = APP_SRC.indexOf(`  function ${name}(`);
    assert.ok(i >= 0, `${name} not found`);
    return APP_SRC.slice(i, APP_SRC.indexOf('\n  }', i) + 4);
  };
  assert.ok(/if \(_pendingSpecs\) return \{ specs: _pendingSpecs \};/.test(inner('_fmtGetData')),
    'readers must see the pending import');
  assert.ok(!/localStorage/.test(inner('_fmtSetPending')),
    'setting the pending list must not write anything');
  assert.ok(/_pendingSpecs = null;/.test(inner('_fmtSave')),
    'saving must clear the pending copy, or the stored list stays shadowed');
});

test('[REGRESSION] discarding a staged import takes its badges with it', () => {
  // Cancel put the classes and DDLs back but left the NEW / OVERWRITTEN badges,
  // the pulsing button and the dimmed top bar pointing at an import that no
  // longer existed. Reported 2026-08-27.
  const close = psFnSource('closeMsgEditor');
  assert.ok(/const live = new Set\(\(_fmtGetData\(\)\.specs \|\| \[\]\)\.map\(_specKey\)\);/.test(close),
    'the discard must check which marked classes actually survived');
  assert.ok(/for \(const k of \[\.\.\._meImportMarks\.keys\(\)\]\) if \(!live\.has\(k\)\) _meImportMarks\.delete\(k\);/.test(close),
    'a badge for a class that was just thrown away must go with it');
  // …and only those: a mark on a class that IS saved was committed by an
  // earlier import and is still owed a look.
  assert.ok(!/_meImportMarks = new Map\(\)/.test(close),
    'discarding one import must not clear badges owed by another');
  // The signal is derived from the marks, so clearing them clears it.
  assert.ok(/_meSyncAttention\(\)/.test(close), 'the pulse and scrim must be re-evaluated after the discard');
});

test('[REGRESSION] closing the Class Editor with unsaved changes asks first', () => {
  // openMsgEditor rebuilds _meState from storage on every open, so unsaved
  // edits do not survive a close — they were thrown away with nothing to undo
  // them, and nothing used to ask. The ✕ is the button people hit on the way
  // past, so it asks; Cancel does not, because choosing Cancel IS choosing to
  // discard. Reported 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/onclick="_meCloseEditor\(\)" title="Close"/.test(src),
    'the close box still discards silently');
  assert.ok(/<button class="btn" onclick="closeMsgEditor\(\)">Cancel<\/button>/.test(src),
    'Cancel must stay the silent discard — it is already an explicit choice');
  const guard = psFnSource('_meCloseEditor');
  assert.ok(/if \(!\(st && st\.dirty\)\) \{ closeMsgEditor\(\); return; \}/.test(guard),
    'a clean editor must close without a dialog');
  assert.ok(/Discard unsaved changes\?/.test(guard), 'the question is not asked in the user\'s words');
  assert.ok(/ok => \{ if \(ok\) closeMsgEditor\(\); \}/.test(guard),
    'answering no must keep the editor open');
  // A PENDING IMPORT is not the editor's to discard: it has its own bar, its own
  // Save and its own Discard, and it outlives the editor being shut.
  const close = psFnSource('closeMsgEditor');
  assert.ok(!/_pendingImport = null/.test(close),
    'closing the editor must not throw away an import it does not own');
});

test('anything the Class Editor owes a Save says so on the button that fixes it', () => {
  // The two import doors leave the app in different states — staged-and-dirty
  // from inside the Class Editor, already-written from the DDL tree — but both
  // end at the same gesture: open the editor, look at what landed, press Save.
  // So both raise the same signal, on whichever button is the next step.
  // Requested 2026-08-27.
  const fn = psFnSource('_meSyncAttention');
  // Unsaved edits raise it too: closing the editor does not discard them, so a
  // change can sit unsaved with nothing on screen saying so. Requested
  // 2026-08-27.
  assert.ok(/const dirty   = !!\(typeof _meState !== 'undefined' && _meState && _meState\.dirty\)/.test(fn),
    'a dirty editor must raise the signal, not just an import');
  assert.ok(/const waiting = _meImportMarks\.size > 0 \|\| impPend \|\| dirty/.test(fn),
    'the signal must cover every reason a Save is owed: badges, a pending import, unsaved edits');
  assert.ok(/_meSyncAttention\(\)/.test(psFnSource('_meSetDirty')),
    'becoming dirty must raise the signal at the moment it happens');
  // While it pulses, Save wears the same look as the pulsing Class Editor
  // button — the two ends of one signal must be recognisably the same thing.
  const css = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.attn-pulse\.btn-primary \{\s*\n\s*background: var\(--surface-raised\) !important;\s*\n\s*color: var\(--accent\) !important;/.test(css),
    'the pulsing Save keeps its filled blue and swallows the glow');
  // …and with nothing to save it is a quiet button, not a 32%-opacity blue one:
  // ghosting the primary fill read as a broken control beside sharp neighbours.
  assert.ok(/#me-save-btn:disabled \{\s*\n\s*opacity: 1;\s*\n\s*background: var\(--surface-raised\);/.test(css),
    'the disabled Save is still a faded primary');
  assert.ok(/save\.classList\.toggle\('attn-pulse', waiting && editorOpen\)/.test(fn),
    'with the editor open, Save is the next step');
  assert.ok(/open\.classList\.toggle\('attn-pulse', waiting && !editorOpen\)/.test(fn),
    'with it closed, the Class Editor button is');
  // The top bar dims behind the lit button — but only for an IMPORT, which
  // arrived without the user asking and has to be looked at. Unsaved edits are
  // their own work in progress and get no spotlight. Requested 2026-08-27.
  assert.ok(/hdr\.classList\.toggle\('attn-dim', \(_meImportMarks\.size > 0 \|\| impPend\) && !editorOpen\)/.test(fn),
    'the scrim must follow the import alone, not every dirty state');
  // A DDL-only import has no classes and so no badges, but it is exactly as
  // unsaved as one that does — and it vanishes on reload if it is not saved.
  assert.ok(/const impPend = !!\(typeof _pendingImport !== 'undefined' && _pendingImport\);/.test(fn),
    'a DDL-only import must raise the signal too, or it is lost in silence');
  // …and it follows the user through the door: the editor's own bar dims while
  // the import is unchecked, so the spotlight is not a trick the top bar played.
  assert.ok(/meHdr\.classList\.toggle\('attn-dim', \(_meImportMarks\.size > 0 \|\| impPend\) && editorOpen\)/.test(fn),
    'the editor bar must dim while an import is unacknowledged');
  // Once the badges are gone, the next dirty edit pulses and nothing dims —
  // both scrims read _meImportMarks, never `dirty`.
  assert.ok(!/attn-dim', *(waiting|dirty)\b/.test(fn),
    'a plain unsaved edit must not darken the room');
  const dimCss = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/header\.attn-dim::after \{ content: ''; position: absolute; inset: 0;/.test(dimCss),
    'the scrim covers the bar it belongs to');
  assert.ok(/header\.attn-dim #dataEditorBtn,\s*\n\.me-header\.attn-dim #me-save-btn \{ position: relative; z-index: 151; \}/.test(dimCss),
    'the button that resolves it must sit ABOVE the scrim, in BOTH bars, or the spotlight points at nothing');
  assert.ok(/header\.attn-dim::after \{[^}]*pointer-events: none;/.test(dimCss),
    'the scrim must not swallow clicks — the app stays usable, the check is only owed');
  // An import from the tree leaves nothing dirty, so Save is disabled — and a
  // pulsing button that cannot be pressed is worse than no signal at all.
  assert.ok(/if \(waiting && editorOpen\) save\.disabled = false;/.test(fn),
    'the pulsing Save button must be pressable');
  // Every edge that changes either half of the condition re-syncs.
  for (const [caller, why] of [
    ['confirmImport',      'the import itself must raise it'],
    ['openMsgEditor',      'opening the editor moves it from the opener to Save'],
    ['closeMsgEditor',     'closing without saving moves it back'],
    ['_meSave',            'saving is the acknowledgement — it must come down'],
    ['_meClearImportMarks','clearing the marks must clear the signal'],
  ]) assert.ok(/_meSyncAttention\(\)/.test(psFnSource(caller)), `${caller}: ${why}`);

  // The pulse runs until the import is acknowledged: the check can outlast a
  // long look through a bundle of forty classes, and a signal that gives up
  // before the work is done was not there when it was needed. Save stops it.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/animation: attn-pulse [\d.]+s ease-in-out infinite;/.test(src),
    'the pulse must last as long as the thing it is pointing at');
  assert.ok(/prefers-reduced-motion: reduce\) \{ \.attn-pulse \{ animation: none; \}/.test(src),
    'a blinking control has to be switchable off for motion sensitivity');
});

test('[REGRESSION] a conflicting import row says "overwrite" once, not twice', () => {
  // The row markup carried an overwrite tag AND .pick-over label::after added
  // another, so every conflict read "overwrite ⚠ overwrite". Reported 2026-08-27.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(!/\.pick-over label::after/.test(src), 'the CSS still adds a second copy of the tag');
  eq((src.match(/⚠ overwrite/g) || []).length >= 1, true, 'the warning glyph went with it');
  // And the group is named the way the app names it everywhere else.
  assert.ok(!/letter-spacing:\.04em">DATA<\/div>/.test(src), 'a picker still calls the class list "DATA"');
  eq((src.match(/letter-spacing:\.04em">CLASSES<\/div>/g) || []).length, 2,
     'both the import and the export picker head the list "CLASSES"');
});

test('[REGRESSION] a class dropped on another list JOINS that list', () => {
  // The drop handler decided only one thing: "the target list is Messages".
  // So dragging a message onto a Data row rewrote it as a message — dragging
  // into Data did nothing at all — and dropping onto a file row reclassified
  // without moving. The target row's kind decides all three now.
  // Reported 2026-08-27.
  const drop = psFnSource('_meSpecDrop');
  assert.ok(!/delete moved\.kind;   \/\/ target list is Messages/.test(drop),
    'the drop still assumes every target is the Messages list');
  assert.ok(/const srcKind = _meKindOf\(_meState\.specs\[src\]\)/.test(drop),
    'the no-op check must compare LISTS, or a cross-list drop onto the same slot is dropped');
  assert.ok(/if \(dst === src && srcKind === tgtKind\) return;/.test(drop),
    'only a move that changes neither list nor position is a no-op');

  // Dropping on a list's empty space means the end of THAT list, whichever it is.
  const onList = psFnSource('_meSpecDropOnList');
  assert.ok(/if \(kind === 'file' \|\| kind === 'other'\) s\.kind = kind; else delete s\.kind;/.test(onList),
    'the empty-space drop must set the kind of the list it landed in');
  assert.ok(/_meState\.specs\.push\(moved\)/.test(onList),
    'and move it to the end of the array, which is the end of that list');
});

test('[REGRESSION] the Test panel gives file classes the filename to match on', () => {
  // The Test panel built its context from a NETARD wrapper only — { source,
  // dest } — so a `filename` recognizer could never pass there whatever the
  // pattern said, and file classes were excluded from the winner outright. The
  // one control for working out why a file class does not match could not test
  // file classes. Reported 2026-08-27.
  const fn = psFnSource('_meRunTest');
  assert.ok(/isFupCopyLog\(text\)[\s\S]{0,80}parseFupCopyLog\(text\)/.test(fn),
    'a FUP COPY capture must be parsed for its wrapper, the way the real flow does');
  assert.ok(/filename: rec\.filename \|\| rec\.filePath \|\| null/.test(fn),
    'the wrapper filename never reaches the recognizers');
  assert.ok(/_testHasFilename \|\| _meState\.specs\[i\]\?\.kind !== 'file'/.test(fn),
    'file classes must compete for the win when the input carries a filename');
  // And with no filename they stay out — they cannot win a real parse either.
  assert.ok(/const _testHasFilename = !!\(testCtx && testCtx\.filename\)/.test(fn),
    'the gate must read the context that was actually built');
});

test('[REGRESSION] a FUP COPY header without KEY is still FUP COPY', () => {
  // KEY n  (%n) is printed for a KEY-SEQUENCED file. An entry-sequenced,
  // relative or unstructured file has no key, and its header runs straight from
  // RECORD n to LEN n. The pattern demanded KEY, so those captures were not
  // recognised as FUP COPY at all — no format badge, no record split, nothing
  // parsed. Reported 2026-08-27.
  const keyed   = fixtureText('test/FUP-test/fup-copy-hex.txt');
  // Record 9 of the fixture is the long-key edge case and prints no (%…) part.
  const keyless = keyed.replace(/ {2}KEY \S+(?: {2}\(%[^)]*\))?/g, '');
  assert.ok(!/KEY/.test(keyless), 'the fixture under test still has a key in it');

  eq(detectFormat(keyless), 'fup-hex', 'a keyless capture is not recognised as FUP COPY at all');
  eq(sandbox.isFupCopyLog(keyless), true, 'the detector and the parser must agree on what a header is');

  const recs = sandbox.parseFupCopyLog(keyless);
  const kept = sandbox.parseFupCopyLog(keyed);
  eq(recs.length, kept.length, 'the same capture must split into the same records with or without keys');
  eq(recs.map(r => r.recNo).join('|'), kept.map(r => r.recNo).join('|'), 'record numbers survive');
  eq(recs.map(r => r.rawMsg).join('|'), kept.map(r => r.rawMsg).join('|'),
     'and so does every byte of the data');
  eq(recs[0].keyNo, null, 'no key printed means no key — not the string "undefined"');
  eq(kept[0].keyNo, '0', 'a printed key is still read');
  // The source detail line is what the record list shows under the file path.
  eq(recs[0].sourceDet, 'RECORD 0', 'a keyless record says which record it is');
  eq(kept[0].sourceDet, 'KEY 0', 'a keyed one still says KEY');

  // The system name is optional too, and always was — record 1 of the fixture
  // carries no \\SYS1. prefix. Pinned so the two optional halves of the header
  // cannot be broken by a change to the other.
  eq(kept[0].filePath, '\\SYS1.$DATA.FINANCE.TXNLOG', 'the system name is kept when printed');
  eq(kept[1].filePath, '$DATA.FINANCE.TXNLOG', 'and is not required');
  eq(sandbox.isFupCopyLog('$DATA.FINANCE.TXNLOG  RECORD 0  LEN 20  13MAY26 14:30\n 000:   3031 3233\n'),
     true, 'neither system name nor key — the plainest header FUP prints');
});

test('extracts pure hex, labelled hex, octal, and fixed-width ASCII bytes', () => {
  deepEq(extractBytes('30313233', 'hex'), [48, 49, 50, 51], 'pure hex');
  deepEq(extractBytes('payload = 41 42 43 44', 'hex'), [65, 66, 67, 68], 'labelled hex');
  deepEq(extractBytes('101 102 377', 'oct'), [65, 66, 255], 'octal');
  P.lineWidth = 3; S.asciiMargin = 0; S.asciiRulerCol = 0;
  deepEq(extractBytes('A\nBC', 'ascii'), [65, 32, 32, 66, 67, 32], 'ASCII padding');
  P.lineWidth = 0;
});

