test('the synthetic-bitmap override case is demonstrated, not just described', () => {
  // The case that motivated the whole feature: a map the DDL never declares,
  // carrying an override. It had five examples of overrides on DDL fields and
  // none on a synthetic one.
  const ex = psHelp['read-bitmap'].examples.find(e =>
    !Array.isArray(e) && /"length"/.test(JSON.stringify(e.spec)) && /"overrides"/.test(JSON.stringify(e.spec)));
  assert.ok(ex, 'read-bitmap ships a synthetic-map override example');
  assert.ok(/bitmap-list/.test(mePsHelpExampleHtml(ex)), 'and it runs');
});

test('the production overflow example is one example, listed by both blocks', () => {
  // when's `greater_than {sizeof}` and read-to-end's `end_at: "field"` only mean
  // anything together, so the card belongs in both places — from ONE definition.
  // Two copies is how the two copies start disagreeing.
  const of = blk => psHelp[blk].examples.filter(e => !Array.isArray(e) && /end_at/.test(JSON.stringify(e.spec)));
  const w = of('when'), r = of('read-to-end');
  eq(w.length, 2, 'when ships the pair');
  eq(r.length, 2, 'and so does read-to-end');
  for (let i = 0; i < 2; i++)
    assert.ok(w[i] === r[i], `card ${i + 1} is the same object, not a copy`);
  // It demonstrates what it claims: nested payload, surplus captured, TAIL safe.
  const ids = e => mePsHelpRunExample(e).fields.map(f => f.id);
  const over = ids(w[0]), exact = ids(w[1]);
  assert.ok(over.includes('GRP.SUB.ITEM2.B2'), 'the deepest leaf is read — the payload really is nested');
  assert.ok(over.includes('GRP.OVERFLOW'), 'the surplus byte is captured');
  assert.ok(!exact.includes('GRP.OVERFLOW'), 'and not captured when the wire agrees');
  for (const r2 of [over, exact]) assert.ok(r2.includes('TAIL'), 'TAIL lands either way');
  // And the accordion shows it under both attributes it demonstrates.
  for (const [blk, attr] of [['when', 'greater_than'], ['read-to-end', 'end_at']])
    assert.ok(psExamplesFor(psHelp[blk], attr).length >= 2,
      `${blk}.${attr} claims the example`);
});

test('the length_mode pair shows the contrast it promises — same bytes, TAIL in two places', () => {
  // The two cards are the whole argument for the attribute: identical DDL and
  // identical payload, and the only difference is where the next DE lands. If
  // they ever stop disagreeing, the reference is claiming something untrue.
  const [strict, smart] = ['"vlg_identifier": "SIZE"}}]', '"length_mode": "smart"}}]']
    .map(m => psHelp['read-bitmap-fields'].examples.find(e =>
      !Array.isArray(e) && e.payload && JSON.stringify(e.spec).replace(/\s/g, '').includes(m.replace(/\s/g, ''))
      && /length_mode/.test(e.what)));
  assert.ok(strict && smart, 'both length_mode examples are still shipped');
  deepEq(strict.payload, smart.payload, 'they must run the SAME bytes, or they compare nothing');
  const tailOf = ex => (mePsHelpRunExample(ex).fields.find(f => f.id === 'TAIL') || {}).value;
  eq(tailOf(strict), 'ETAI', 'strict: TAIL is dragged a byte early, exactly as the card says');
  eq(tailOf(smart),  'TAIL', 'smart: TAIL lands where the length said it would');
  eq(mePsHelpRunExample(smart).fields.some(f => f.id === 'EMV.<unmapped>'), true,
     'and the surplus byte is on screen under the name the card promises');
});

test('every executable example produces the fields it claims to', () => {
  // The panel RUNS these against their own payloads, so a broken one is not a
  // stale sentence — it is an error table under a heading that promises a result.
  const bad = [];
  for (const [blk, info] of Object.entries(psHelp).concat([['(shared)', { examples: psCommonExamples }]]))
    for (const ex of info.examples) {
      if (Array.isArray(ex) || !ex.payload) continue;
      const ctx = mePsHelpRunExample(ex);
      const errs = (ctx.fields || []).filter(f => f.error);
      if (ex.expectError) {
        if (!errs.length) bad.push(`${blk}: "${ex.what}" was meant to show an error and did not`);
        continue;
      }
      if (errs.length) bad.push(`${blk}: "${ex.what}" → ${errs.map(e => e.error).join(' | ')}`);
      else if (!(ctx.fields || []).length) bad.push(`${blk}: "${ex.what}" produced no fields`);
      // token-area fills ctx.tokens, not ctx.fields — a silently empty token
      // area would still have passed the check above.
      else if (JSON.stringify(ex.spec).includes('token-area') && !(ctx.tokens || []).length)
        bad.push(`${blk}: "${ex.what}" selected no tokens`);
    }
  deepEq(bad, [], 'help examples that do not run');
});

