test('the Class Editor page fills the viewport instead of floating in it', () => {
  const css = _DE_CSS();
  const overlay = /\.me-overlay\s*\{([^}]*)\}/.exec(css);
  const shell   = /\.me-shell\s*\{([^}]*)\}/.exec(css);
  assert.ok(overlay && shell, '.me-overlay / .me-shell rules are gone');
  // A page has nothing to dim: the scrim said "the thing behind this still
  // matters", and nothing behind it is reachable.
  assert.ok(!/var\(--scrim\)/.test(overlay[1]), 'a full page must not paint a scrim');
  for (const prop of ['max-width', 'box-shadow', 'border-radius']) {
    assert.ok(!new RegExp(prop).test(shell[1]), `the shell still carries a dialog's ${prop}`);
  }
  assert.ok(!/\d+vw|\d+vh/.test(shell[1]), 'the shell is still sized as a card inside the viewport');
  // Pinned by an existing test: .cfg-dim resolves against this box.
  assert.ok(/overflow\s*:\s*hidden/.test(shell[1]), 'the shell must still clip');
});

test('Test is a subpanel of Entities, not a panel across the page', () => {
  // Testing IS working on the entity list: a run paints every row and picks
  // one. As a bottom bar it carried a duplicate list; as a right-hand column it
  // sat at the far edge from the list it annotates. It lives in the column now,
  // under the list, with a gutter between them.
  const sidebar = html.slice(html.indexOf('id="me-sidebar"'), html.indexOf('id="me-splitter"'));
  assert.ok(sidebar.length > 500, 'could not isolate the Entities column');
  const order = ['id="me-ent-list"', 'id="me-sect-files"', 'id="me-test-resizer"', 'id="me-test-sub"'];
  let at = -1;
  for (const needle of order) {
    const i = sidebar.indexOf(needle);
    assert.ok(i > 0, `${needle} is not inside the Entities column`);
    assert.ok(i > at, `${needle} is out of order: the column reads list → gutter → Test`);
    at = i;
  }
  // A stacked split takes the horizontal bar — the one that drags on Y.
  assert.ok(/id="me-test-resizer"[^>]*class="resizer-v"|class="resizer-v"[^>]*id="me-test-resizer"/.test(html),
    'the Test gutter must be a .resizer-v, which drags vertically');
  // The page is two columns: nothing sits to the right of the editor.
  const main = html.slice(html.indexOf('<div class="me-main">'));
  const afterRight = main.slice(main.indexOf('class="me-right"'));
  assert.ok(!/resizer-h/.test(afterRight.slice(0, afterRight.indexOf('</div>\n    </div>'))),
    'a third column reappeared to the right of the editor');
  // The old bottom bar and the old right column are gone in full, not hidden.
  for (const dead of ['me-test-bar', 'me-test-body', 'me-test-arr', 'me-test-list',
                      'me-test-pane', 'me-test-splitter', '_meToggleTest('])
    assert.ok(!html.includes(dead), `${dead} survived the move — an older Test layout is still wired`);
});

test('the entity list is not duplicated — verdicts land on the sidebar', () => {
  // The Test bar carried its own copy of every entity, in the same order, three
  // inches from the sidebar that already listed them. Reported as duplication:
  // the sidebar is the list, a test run only annotates it.
  const render = psFnSource('_meTestRenderList');
  assert.ok(/_meState\.testResults\s*=/.test(render), 'the verdicts are not published to state');
  assert.ok(/_meRenderSidebar\(\)/.test(render), 'the verdicts never reach the sidebar');
  assert.ok(!/getElementById\('me-test-list-body'\)/.test(html),
    'something still writes to the removed verdict list');

  // The sidebar renderer reads them back and paints the ROW — three states, so
  // an entity that matches but is shadowed is never coloured like a miss.
  const list = psFnSource('_meRenderSpecList');
  assert.ok(/_meState\.testResults/.test(list), 'the sidebar never reads the verdicts');
  for (const cls of ['tv-win', 'tv-pass', 'tv-fail'])
    assert.ok(list.includes(cls), `the row verdict is missing the ${cls} state`);
  assert.ok(!/me-rec-dot/.test(list), 'the row still adds the old dot beside the swatch');
  // Colour is never the only carrier — the winner says WINS in words too.
  assert.ok(/me-test-win/.test(list), 'the winning row has no WINS badge');
  const css = _DE_CSS();
  for (const cls of ['tv-win', 'tv-pass', 'tv-fail'])
    assert.ok(new RegExp(`\\.me-item\\.${cls}\\s*\\{[^}]*background`).test(css),
      `.me-item.${cls} paints no row background`);
  // Selected AND coloured: .me-item.active would repaint the row accent-blue on
  // top of green, so the verdict keeps the background and selection moves to a
  // bar. Declared after .me-item.active, or it never wins.
  assert.ok(css.indexOf('.me-item.tv-win{') > css.indexOf('.me-item.active{'),
    'the verdict colours are declared before .me-item.active, which overrides them');
  assert.ok(/\.me-item\.tv-win\.active:not\(\.me-item-forced\)\s*\{[^}]*box-shadow:\s*inset/.test(css),
    'a selected verdict row shows no selection marker');

  // A verdict that outlives the recognizer it was computed from is a lie. Every
  // place that drops the per-entity verdict drops the cross-entity one too.
  const stale = [...APP_SRC.matchAll(/_meState\.recTest = null;([^\n]*\n[^\n]*)/g)]
    .filter(m => !/testResults = null/.test(m[1]));
  eq(stale.length, 1,
    'every recTest reset but the selection one must also clear testResults');
});

test('the column and its subpanel both collapse, and remember it', () => {
  for (const [fn, gutter, key, what] of [
    ['_meSetSidebarCollapsed', 'me-splitter',     'up_me_sidebar_collapsed', 'Entities column'],
    ['_meSetTestSubCollapsed', 'me-test-resizer', 'up_me_test_collapsed',    'Test subpanel'],
  ]) {
    const setter = psFnSource(fn);
    assert.ok(/classList\.toggle\('collapsed'/.test(setter), `${what}: no collapsed class`);
    // A gutter left live by a closed panel is a handle with nothing behind it.
    assert.ok(new RegExp(`'${gutter}'\\)\\?\\.classList\\.toggle\\('inert'`).test(setter),
      `${what}: the gutter is not made inert with the panel`);
    assert.ok(/_meSetToggleBtn\(/.test(setter), `${what}: the button glyph is not updated`);
    assert.ok(setter.includes(key), `${what}: the state is not persisted`);
  }
  // Restoring goes through the same setters, so a restored panel can never
  // disagree with its button or its gutter.
  const init = psFnSource('_meInitSplitter');
  assert.ok(/_meSetSidebarCollapsed\(sbC\)/.test(init) && /_meSetTestSubCollapsed\(tsC\)/.test(init),
    'the restore path sets the class directly instead of going through the setters');
  assert.ok(/id="me-sidebar-toggle"[^>]*onclick="_meToggleSidebar\(\)"/.test(html),
    'the Entities column has no collapse button');
  assert.ok(/id="me-test-toggle"[^>]*onclick="_meToggleTestSub\(\)"/.test(html),
    'the Test subpanel has no collapse button');
  // Collapsed, the subpanel must give its height back — height:auto, not a
  // hidden body inside a box that still reserves 420px.
  const css = _DE_CSS();
  assert.ok(/\.me-test-sub\.collapsed\{[^}]*height:\s*auto\s*!important/.test(css),
    'a collapsed subpanel leaves a gap where its body was');
});

test('a collapsed Class Editor rail reads top-down, like every other panel', () => {
  // Same trap the four main panels hit: rotate(180deg) flips the flex axis, so
  // flex-start is the BOTTOM. The rail is new markup and inherits none of the
  // #ddlPanel fix, so it needs its own flex-end.
  const css = _DE_CSS();
  const rule = /\.me-pane\.collapsed \.me-pane-title\s*\{([^}]*)\}/.exec(css);
  assert.ok(rule, 'the collapsed rail title rule is gone');
  assert.ok(/writing-mode\s*:\s*vertical-rl/.test(rule[1]), 'the rail title is not vertical');
  if (/transform\s*:\s*rotate\(180deg\)/.test(rule[1])) {
    // The LAST declaration is the one that paints. Matching anywhere in the
    // rule passes on a flex-end that a later flex-start overrides.
    const decls = [...rule[1].matchAll(/justify-content\s*:\s*([\w-]+)/g)].map(m => m[1]);
    eq(decls[decls.length - 1], 'flex-end',
      'a rotated rail title anchored at flex-start sits at the BOTTOM');
  }
});

test('every pane resizes the way its gutter implies, and all of them persist', () => {
  const init = psFnSource('_meInitSplitter');
  const rez  = /const _ME_RESIZERS = \[([\s\S]*?)\n\];/.exec(APP_SRC);
  assert.ok(rez, '_ME_RESIZERS is gone');
  // The sign follows from which SIDE of its gutter a pane sits on: panes
  // declared before their gutter grow with the pointer, after it grow against.
  // One shared direction is the bug waiting here — the Test subpanel and the
  // Test input share an axis and must move opposite ways.
  const EXPECT = [
    ['me-sidebar',    'x',  1, 'the Entities column, left of its gutter'],
    ['me-test-sub',   'y', -1, 'the Test subpanel, below its gutter'],
    ['me-test-input', 'y',  1, 'the Test input, above its gutter'],
  ];
  for (const [el, axis, sign, what] of EXPECT) {
    const row = new RegExp(`el: '${el}',[^\\n]*axis: '(\\w)', sign: (-?1)`).exec(rez[1]);
    assert.ok(row, `${what}: no resizer entry`);
    eq(row[1], axis, `${what}: wrong axis`);
    eq(row[2], String(sign), `${what}: grows the wrong way`);
  }
  // DOM order has to agree with the sign, or the entry is a guess that happens
  // to be right: gutter AFTER the pane means sign 1, BEFORE it means -1.
  for (const [el, , sign] of EXPECT) {
    const g = new RegExp(`el: '${el}',\\s*gutter: '([\\w-]+)'`).exec(rez[1]);
    const iPane = html.indexOf(`id="${el}"`), iGut = html.indexOf(`id="${g[1]}"`);
    assert.ok(iPane > 0 && iGut > 0, `${el}: pane or gutter missing from the markup`);
    eq(iGut > iPane, sign === 1, `${el}: DOM order and drag direction disagree`);
  }
  assert.ok(/cfg\.sign \* \(\(cfg\.axis === 'x' \? e\.clientX : e\.clientY\) - start\)/.test(init),
    'the drag does not apply the per-pane direction');
  assert.ok(/Math\.max\(cfg\.min\(\), Math\.min\(cfg\.max\(\)/.test(init), 'the drag is unclamped');
  assert.ok(/localStorage\.setItem\(cfg\.key/.test(init), 'a size that forgets on reload');
  // Ceilings are measured from live layout — both vertical panes are bounded by
  // a container that is itself resizable, so a constant would be wrong at one
  // size or the other. And restore must not apply a ceiling: it runs before the
  // layout it would measure, and would clamp a good saved size to the minimum.
  for (const fn of ['_meElH\\(\'me-sidebar\'\\)', '_meElH\\(\'me-test-main\'\\)'])
    assert.ok(new RegExp(`max: \\(\\) => Math\\.max\\(\\w+, ${fn}`).test(rez[1]),
      `a vertical pane has a fixed ceiling instead of a measured one`);
  assert.ok(/= Math\.max\(cfg\.min\(\), saved\) \+ 'px'/.test(init),
    'restore clamps against a ceiling it cannot measure yet');
});

test('the Test input is the Data Input panel, not a lesser copy of it', () => {
  // The point of Test is solving a parse without walking back to the main
  // panel. A three-button AUTO/HEX/ASCII toggle sent the user straight back the
  // moment the bytes were EBCDIC, octal or a hexascii dump.
  const main = /<select id="fmtForceSelect"[\s\S]*?<\/select>/.exec(html);
  const test = /<select id="me-test-fmt"[\s\S]*?<\/select>/.exec(html);
  assert.ok(main && test, 'one of the two format selects is gone');
  const opts = s => [...s.matchAll(/<option value="([^"]*)">([^<]*)</g)].map(m => m[1] + '=' + m[2]);
  deepEq(opts(test[0]), opts(main[0]),
    'the Test format select must offer exactly the main panel\'s formats, same values');

  // Same bar, under the header, as on the main panel — not crammed into it.
  const sub = html.slice(html.indexOf('id="me-test-sub"'), html.indexOf('id="me-test-out"'));
  const iHdr = sub.indexOf('class="me-sub-hdr"');
  const iCfg = sub.indexOf('id="me-test-cfg"');
  const iCm  = sub.indexOf('id="me-test-input"');
  assert.ok(iHdr >= 0 && iCfg > iHdr && iCm > iCfg,
    'the subpanel must read header → config bar → input, like the main panel');
  // On the id ATTRIBUTE, not a substring of the bar: "me-lw-widget-gone"
  // contains "me-lw-widget", and a renamed control would have passed.
  for (const id of ['me-test-fmt', 'me-test-fmt-badge', 'me-test-cnt-badge', 'me-lw-widget'])
    assert.ok(new RegExp(`id="${id}"`).test(sub.slice(iCfg, iCm)),
      `${id} is not in the Test config bar`);

  // A real editor, sharing the main input's highlight classes.
  assert.ok(/id="me-test-input" class="cm-host me-test-cm"/.test(html),
    'the Test input is not a CodeMirror host');
  assert.ok(!/me-test-ta/.test(html), 'the old textarea styling survived');
  const css = _DE_CSS();
  for (const cls of ['cm-hl-active', 'cm-hl-hover'])
    assert.ok(new RegExp(`\\.me-test-cm \\.${cls}`).test(css), `the Test input cannot paint ${cls}`);

  // One badge table, not two — the same format must not be named two ways.
  assert.ok(/const _FMT_BADGE = \{/.test(APP_SRC), 'the badge map is not shared');
  assert.ok(/const fmtMap = _FMT_BADGE;/.test(psFnSource('updateBadges')),
    'updateBadges kept a private copy of the badge map');
  assert.ok(psFnSource('_meTestUpdateFmtState').includes('_FMT_BADGE'),
    'the Test bar does not use the shared badge map');
});

test('one Line Width preference, two widgets, no loop between them', () => {
  // P.lineWidth is a saved preference and belongs to the app, so both bars edit
  // the same number. The ids differ, so the handlers take a prefix.
  for (const fn of ['lwStartEdit', 'lwCommit', 'lwCancel']) {
    const src = psFnSource(fn);
    assert.ok(new RegExp(`function ${fn}\\(pfx\\)`).test(src), `${fn} cannot address the second widget`);
    assert.ok(/_lwEls\(pfx\)/.test(src), `${fn} still looks the elements up by fixed id`);
  }
  assert.ok(/onclick="lwStartEdit\('me-lw-'\)"/.test(html), 'the Test widget is not wired to its own ids');
  assert.ok(/onclick="lwStartEdit\(\)"/.test(html), 'the main widget lost its default');
  // Both displays repaint from one place.
  const upd = psFnSource('_lwUpdateDisplay');
  assert.ok(/me-lw-display/.test(upd), 'the Test display is never repainted');
  // …and the repaint must not come back round: _lwUpdateDisplay calls the Test
  // sync, so the Test sync must never call _lwUpdateDisplay.
  assert.ok(!/_lwUpdateDisplay\(/.test(psFnSource('_meLwSync')),
    'the Line Width sync calls back into the function that calls it');
});

test('a field row lights its own bytes in the Test input', () => {
  // The gesture the Data Input panel answers, answered here — otherwise
  // reading a parse against the actual bytes still means leaving the panel.
  const tbl = psFnSource('_meTestFieldTable');
  assert.ok(/data-fid="/.test(tbl), 'field rows carry no id for the highlight to key on');
  assert.ok(/f\.startByte != null/.test(tbl),
    'rows with no bytes must not offer a gesture that cannot do anything');
  const bind = psFnSource('_meTestBindRowHL');
  for (const [ev, what] of [['onmouseenter', 'hover'], ['onmouseleave', 'hover out'], ['onclick', 'pin']])
    assert.ok(bind.includes(ev), `no ${what} handler on the field rows`);
  // Clicking the pinned row again releases it, or the only way to drop a
  // highlight is to run the test over.
  assert.ok(/_meTestSelFid === fid \? null : fid/.test(bind), 'a pinned row cannot be unpinned');
  // The map is the Test input's own: the two inputs hold different text.
  const run = psFnSource('_meRunTest');
  assert.ok(/_meTestByteMap = netardBcm \|\| _meTestBuildByteMap\(text, inputFmt\)/.test(run),
    'the byte map is not rebuilt from the text and format the run actually used');
  // buildByteCharMap says it is for NON-NETARD input, and it is: a wrapped
  // record's map is built by parseNetardLog as it strips the wrapper. Handing
  // the wrapped text to buildByteCharMap returned a map for the wrong string,
  // and hovering a field lit nothing at all.
  assert.ok(/netardBcm = Array\.isArray\(rec\.byteCharMap\) \? rec\.byteCharMap : null/.test(run),
    'a NETARD record\'s own byte map is discarded');
  assert.ok(run.indexOf('netardBcm = Array.isArray') < run.indexOf('_meTestByteMap ='),
    'the record map is captured after the point it is used');
  assert.ok(!/S\.messages/.test(psFnSource('_meTestHLRanges')),
    'the Test highlight reads the MAIN panel\'s parsed messages');
});

test('the results table does not spend a column saying the field name twice', () => {
  // Reported: every row read "TYP  TYP", "RTE.STAT  STAT". A DDL definition
  // with no comment describes itself, and a qualified id ends in the leaf it
  // describes — so the description column was the name again, and it pushed
  // size and offset off the right edge.
  const tbl = psFnSource('_meTestFieldTable');
  // Size and offset sit between the name and the data: they say where the
  // value was read, so they are passed on the way to it — and at the far right
  // they were the first thing a narrow panel clipped.
  const cells = [...tbl.matchAll(/<td class="me-test-(\w+)"/g)].map(m => m[1]);
  deepEq(cells, ['fid', 'fid', 'flen', 'fbytes', 'fval', 'fhex'],
    'the field row is not five columns in order: name, size, offset, value, hex');
  // The error row spans the rest of the table exactly.
  const span = /<td colspan="(\d+)" class="me-test-ferr"/.exec(tbl);
  assert.ok(span, 'the error row is gone');
  eq(span[1], '4', 'the error row no longer spans the remaining columns');

  // The description is not dropped, only folded in — and only when it adds
  // something. Both halves matter: suppressing it always would lose the ISO
  // rows that read "Primary Bitmap" or "Bit 19 — no definition in DDL".
  const helper = psFnSource('_meTestExtraDesc');
  assert.ok(/d === id \|\| id\.endsWith\('\.' \+ d\)/.test(helper),
    'the description is suppressed by something other than "it is the id again"');
  assert.ok(/return ` <span class="me-test-fdesc">/.test(helper),
    'a description that says something new is never rendered');
  assert.ok(/\$\{desc\}/.test(tbl), 'the table does not use the folded description');

  // Widths come from the header cells now (see the column test below), so no
  // body cell may declare one — a td width fights table-layout:fixed and the
  // drag silently does nothing.
  const css = _DE_CSS();
  for (const c of ['fid', 'flen', 'fbytes', 'fval', 'fhex'])
    assert.ok(!new RegExp(`\\.me-test-${c}\\{[^}]*[^-]width:`).test(css),
      `.me-test-${c} declares a width, which overrides the column it belongs to`);
});

test('the results table has real columns: named, sized, draggable', () => {
  // A header per column, generated from one list — a column added to the body
  // and forgotten in the header would leave the table a cell short and every
  // width off by one.
  const cols = /const _ME_TEST_COLS = \[([\s\S]*?)\n\];/.exec(APP_SRC);
  assert.ok(cols, '_ME_TEST_COLS is gone');
  const keys = [...cols[1].matchAll(/key: '(\w+)'/g)].map(m => m[1]);
  deepEq(keys, ['fld', 'len', 'off', 'val', 'hex'], 'the column list does not match the row order');
  const tbl = psFnSource('_meTestFieldTable');
  assert.ok(/_ME_TEST_COLS\.map\(/.test(tbl), 'the header is hand-written instead of built from the list');
  assert.ok(/<thead>/.test(tbl), 'the table has no header row');
  // Exactly one column absorbs the slack, or the table either leaves a gap or
  // scrolls sideways.
  eq([...cols[1].matchAll(/flex: true/g)].length, 1, 'exactly one column must absorb the leftover width');
  // The last column gets no handle: there is nothing on its right to take from.
  assert.ok(/i < _ME_TEST_COLS\.length - 1/.test(tbl),
    'the last column has a resize handle with no neighbour to steal from');

  const css = _DE_CSS();
  assert.ok(/\.me-test-ftbl-cols\{[^}]*table-layout:\s*fixed/.test(css),
    'without table-layout:fixed the browser re-fits columns to content and a dragged width lasts one render');
  // Scoped to the field table: the token table beside it has three columns of
  // its own and no header to size them from.
  assert.ok(!/\.me-test-ftbl\{[^}]*table-layout/.test(css),
    'fixed layout is applied to every .me-test-ftbl, including the token table');

  // The drag itself is the shared implementation (see "column resize — one
  // implementation, two tables"); what is asserted here is that this table is
  // wired into it, with the knobs this table needs.
  assert.ok(/const _meTestInitColResize = \(\) => _meColInitResize\(_ME_COLRZ\.test\)/.test(APP_SRC),
    'the results table does not use the shared resizer');
  const tcfg = /test:\s*\{([\s\S]*?)\n  \},/.exec(APP_SRC);
  assert.ok(tcfg, 'the results table has no resizer config');
  assert.ok(/table:\s*'\.me-test-ftbl-cols'/.test(tcfg[1]) && /wrap:\s*'#me-test-out'/.test(tcfg[1]),
    'the config points at the wrong table or wrap');
  assert.ok(/saveAll:\s*true/.test(tcfg[1]),
    'saving only the dragged columns lets the next fit hand the stolen width back');
  // A column dragged to nothing needs a way back. This table has no "Reset
  // columns" button beside it, so the gesture is the only route.
  assert.ok(/resetOnDblClick:\s*true/.test(tcfg[1]),
    'a column dragged to nothing stays there — nothing reaches the reset');
  assert.ok(/handle\.ondblclick/.test(psFnSource('_meColInitResize')),
    'the shared resizer never honours the double-click reset');
  assert.ok(/double-click to reset/.test(html), 'the reset gesture is not discoverable from the handle');

  // Clicking a header lights the column, the same as the Field Map and Parse
  // Results — with five resizable columns the boundaries have to be visible to
  // aim a drag at. Through the SHARED helper, not a third copy of it.
  const run = psFnSource('_meRunTest');
  assert.ok(/_meInitColHighlight\('\.me-test-ftbl-cols'\)/.test(run),
    'the results table has no column highlight');
  // And the drag handle is not a selection target: the helper has to know this
  // table's handle by name, or every resize would also toggle the highlight.
  const hi = psFnSource('_meInitColHighlight');
  assert.ok(/me-test-resizer/.test(hi),
    'dragging this table\'s column edge would also toggle the column highlight');
  assert.ok(/\.me-test-ftbl-cols th\{[^}]*cursor:\s*pointer/.test(_DE_CSS()),
    'the header does not say it can be clicked');

  // Hover and select use the app's tokens, which are the same ones the message
  // input paints a highlighted field with. Hovering a row and watching its
  // bytes light up is ONE gesture; a private tint for the row made it read as
  // two unrelated things happening at once.
  const c = _DE_CSS();
  assert.ok(/\.me-test-ftbl tr:hover td\{background:\s*var\(--hl-hover\)/.test(c),
    'the row hover invents its own tint instead of using --hl-hover');
  assert.ok(/\.me-test-ftbl tr\[data-fid\]\.sel td\{[^}]*color:var\(--hl-text\)/.test(c),
    'a selected row does not take the highlight text colour');
  // Every column, including the ones deliberately quiet at rest — a row that
  // lights in four columns of five reads as half-selected.
  assert.ok(/tr\[data-fid\]\.sel td\.me-test-fhex\{[^}]*color:var\(--hl-text\)/.test(c),
    'the hex column stays dim while the rest of the row lights');
  // …which only works because the cell holds the text directly: a child span
  // repeating the class would keep its own colour.
  assert.ok(!/<span class="me-test-fhex">/.test(psFnSource('_meTestFieldTable')),
    'the hex cell wraps its text in a span, which keeps its own colour when the row lights');
  // And because nothing in the row is quieted with `opacity`. opacity fades the
  // whole cell, background included, so the row's translucent tint composited
  // over a faded box and the hex cell landed on a visibly different colour from
  // the four beside it (#223144 against #24364D). Quiet by COLOUR here.
  for (const cls of ['fid', 'flen', 'fbytes', 'fval', 'fhex']) {
    // Anchored: unanchored, `.me-test-fhex{` also matches inside
    // `.sel td.me-test-fhex{…}`, and the first hit is that one — so the
    // base rule's opacity went unread and the check passed on the bug.
    const rule = new RegExp(`[}\\s]\\.me-test-${cls}\\{([^}]*)\\}`).exec(c);
    if (rule) assert.ok(!/opacity/.test(rule[1]),
      `.me-test-${cls} uses opacity, which fades its background out of step with the row`);
  }
  assert.ok(!/tr\[data-fid\]\.sel td\.me-test-fhex\{[^}]*opacity/.test(c),
    'the highlighted hex cell is faded, so it composites to a different colour than the rest of the row');
});

test('red means the waterfall rejected it, never "we did not get there"', () => {
  // Reported: STM won, and PSTM and everything under it were painted red.
  // Detection stops at the first match, so those were never evaluated — red
  // claimed a rejection that never happened. Only rows the walk actually
  // reaches can fail; past the winner a row is either shadowed (it WOULD have
  // matched, which is worth saying) or simply not reached.
  const run = psFnSource('_meRunTest');
  const reached = /const reached = new Set\(\);\n\s*for \(const i of order\) \{ reached\.add\(i\); if \(i === winnerIdx\) break; \}/.exec(run);
  assert.ok(reached, 'the run does not compute which entities the waterfall reaches');
  // It must be built from `order` — the detection walk — not from the raw spec
  // array, which is a different sequence and includes the file specs.
  assert.ok(run.indexOf('const order') < run.indexOf('const reached'),
    'the reached set is built before detection order is known');
  assert.ok(/_meTestRenderList\(all, winnerIdx, reached\)/.test(run), 'the set never reaches the list');
  assert.ok(/testResults = \{ results, winnerIdx, reached \}/.test(psFnSource('_meTestRenderList')),
    'the set is not published to state');

  // Four states on the row, and the order of the ternary is the claim: won →
  // shadowed → failed → not reached. Testing `reached` before `passed` would
  // dim a shadowed row and lose the warning.
  const list = psFnSource('_meRenderSpecList');
  assert.ok(/won \? 'tv-win' : passed \? 'tv-pass' : reached \? 'tv-fail' : 'tv-skip'/.test(list),
    'the row verdict does not distinguish "failed" from "not reached"');
  assert.ok(/tr\.reached instanceof Set \? tr\.reached\.has\(i\) : true/.test(list),
    'a result without a reached set must not silently dim every row');
  const css = _DE_CSS();
  const skip = /\.me-item\.tv-skip\{([^}]*)\}/.exec(css);
  assert.ok(skip, '.me-item.tv-skip has no rule');
  assert.ok(!/background/.test(skip[1]),
    'a not-reached row must not be coloured — every colour here is a claim about a test that ran');
});

test('a run answers "which entity" before it answers "what fields"', () => {
  const run = psFnSource('_meRunTest');
  // Detection over EVERY entity, and the section that reports it, must both
  // come before the parse. Reading the parse of the previously-selected entity
  // above the verdict that says nothing matched is the confusion being fixed.
  const iAll    = run.indexOf('_meState.specs.map(s => _fmtTestSpecs');
  const iDetect = run.indexOf("_meTestSection('Detection'");
  const iParse  = run.indexOf('_meExecParseSpec(');
  assert.ok(iAll > 0 && iDetect > 0 && iParse > 0, 'the run no longer has all three stages');
  assert.ok(iAll < iDetect && iDetect < iParse,
    'the run must detect, report the verdict, then parse — in that order');

  // The winner becomes the selection; no winner means no selection, so the
  // panel never shows a parse the app would not have produced.
  assert.ok(/if \(autoSelect && winnerIdx !== _meState\.selIdx\) _meSelectItem\('msg', winnerIdx\)/.test(run),
    'the winner is not auto-selected');
  assert.ok(/const item = _meCurItem\(\);/.test(run) && run.indexOf('const item = _meCurItem();') > iAll,
    'the selected item is read before detection could have changed it');
  const bail = run.indexOf('if (!item) {');
  assert.ok(bail > iDetect && bail < iParse,
    'with nothing selected the run must stop after the verdict, not skip it');

  // Clicking a row is the user overriding the pick — re-running must not snap
  // the selection back to the winner.
  assert.ok(/_meRunTest\(\{ autoSelect: false \}\)/.test(psFnSource('_meRenderSpecList')),
    'a row click re-runs with auto-select on, so the click is undone immediately');
});

test('a lost mouseup cannot glue a column to the pointer', () => {
  // Reproduced in the preview: release the button where the document never
  // sees the mouseup — outside the window, or eaten by another handler — and
  // the drag stayed armed. Every later mouse MOVE then resized the column,
  // with no button held, and nothing but a reload stopped it.
  const init = psFnSource('_meInitSplitter');
  const move = /addEventListener\('mousemove',([\s\S]*?)\n  \}\);/.exec(init);
  assert.ok(move, 'the mousemove handler is gone');
  assert.ok(/e\.buttons/.test(move[1]),
    'the drag trusts mouseup alone — a move with no button held must end it');
  assert.ok(/endDrag\(\)/.test(move[1]),
    'it notices the button is up but does not finish the drag (so no width is saved)');
  // And the same teardown runs either way — a bail-out that skipped the save
  // would drop the width the user just dragged to.
  assert.ok(/addEventListener\('mouseup', endDrag\)/.test(init),
    'mouseup and the buttons check must run the same teardown');
});

// ── The compiled-DDL cache must outlive a release ───────────────────────────
console.log('\ncompiled-DDL cache — keyed on the compiler, not the app');

test('the compiled cache is keyed per FILE, and survives a release', () => {
  // Two separate regressions live here.
  //
  // 1) It used to be gated on APP_VERSION, so every release threw the whole
  //    cache away and the next parse recompiled every definition.
  // 2) It was stored and hashed per SUBVOLUME. BASE/DDL alone holds most of a
  //    300-definition tree, so editing one file recompiled every file beside
  //    it — even though the compiled entries were always per-file
  //    ({ path, defName, defs }); only the key and the hash were coarse.
  const src = fs.readFileSync('./source.html', 'utf8');

  assert.ok(/const DDL_COMPILER_VERSION\s*=\s*\d+/.test(src),
    'a compiler version must exist to key the cache on');
  assert.ok(/function _fileHash\(vol, sv, file\)/.test(src),
    'a per-file hash must exist — a subvolume hash cannot express one changed file');

  const put = /store\.put\(\{\s*fk[\s\S]{0,240}?\}\)/.exec(src);
  assert.ok(put, 'cache write not found, or no longer keyed by file');
  assert.ok(/compilerVersion:\s*DDL_COMPILER_VERSION/.test(put[0]),
    'the entry must record the compiler version');
  assert.ok(/hash:\s*_fileHash\(/.test(put[0]),
    'the entry must be hashed on the FILE, not the subvolume');

  const gate = /if \(stored\.hash !== _fileHash\([\s\S]{0,140}?\)\s*\{/.exec(src);
  assert.ok(gate, 'per-file restore gate not found');
  assert.ok(/stored\.compilerVersion !== DDL_COMPILER_VERSION/.test(gate[0]),
    'the restore gate must compare the COMPILER version');
  assert.ok(!/stored\.appVersion === APP_VERSION/.test(src),
    'keying on APP_VERSION makes every release a full recompile');

  // The coarse hash is gone entirely — leaving it invites a caller back.
  assert.ok(!/function _svHash\(/.test(src),
    '_svHash should be removed once nothing decides reuse per subvolume');
});

// ── Expand all / collapse all must not sweep in the inverted key ────────────
console.log('\ntree — expand all leaves the inverted key alone');

test('expand-all never touches the missing-refs key', () => {
  // S.treeExp holds node keys where PRESENT = expanded, plus one key,
  // '::missing-refs', where PRESENT = COLLAPSED. Sweeping every key in the Set
  // would collapse Missing refs on "expand all" and open it on "collapse all" —
  // backwards on both. _treeExpandableKeys builds its list from the DDL tree,
  // so the inverted key cannot get in by construction rather than by filtering.
  const fn = /function _treeExpandableKeys\(\)\s*\{([\s\S]*?)\n\}/.exec(APP_SRC);
  assert.ok(fn, '_treeExpandableKeys not found');
  assert.ok(!/_MISSREF_KEY/.test(fn[1]),
    'the key list must be built from the tree, never from the Set');
  assert.ok(/S\.ddlTree/.test(fn[1]), 'it is derived from the DDL tree');

  const toggle = /function toggleTreeExpandAll\(\)\s*\{([\s\S]*?)\n\}/.exec(APP_SRC);
  assert.ok(toggle, 'toggleTreeExpandAll not found');
  assert.ok(!/treeExp\.clear\(\)/.test(toggle[1]),
    'clearing the Set would take the inverted key with it — remove keys individually');
  assert.ok(/_treeExpandableKeys\(\)/.test(toggle[1]),
    'it must operate on the derived list');
});

// ── "Not found in bound DDLs" needs bound DDLs to be true ───────────────────
console.log('\nparse-spec lint — no bindings is one problem, not many');

test('field references are not reported missing when nothing is bound', () => {
  // With no binding, ddlIds is empty, so every reference "was not found" — and
  // the panel filled with red about fields that are probably fine, all caused by
  // the single fact the user already knows and that read-ddl states on its own
  // line. The sibling checks (read-bitmap.field, seg-map) always guarded on
  // bindingCount && ddlIds.size; checkRef did not.
  const lint = sandbox._t.mePsLintWarns;
  const spec = [{ read: { field: 'TYP' } },
                { 'read-ddl': { binding: 0, from: 'ISO_PFX', until: 'MTI' } }];

  const unbound = lint({ label: 'X', ddl_bindings: [], parse_spec_binary: spec }, spec);
  assert.ok(!unbound.some(w => /not found in bound DDLs/.test(w)),
    `nothing is bound, so nothing can be "not found" — got: ${JSON.stringify(unbound)}`);
  assert.ok(unbound.some(w => /no DDL bindings/.test(w)),
    'the one real problem must still be reported');
  assert.strictEqual(unbound.length, 1,
    `one cause should read as one warning — got: ${JSON.stringify(unbound)}`);
});

// ── An armed entity override has to be visible wherever it changes behaviour ─
console.log('\nentity override — the app must say when it is on');

test('the detection summary does not claim a forced run was evaluated', () => {
  // A forced trace carries ONE row and that row is `passed`, so the near-miss
  // loop dropped it and the summary printed "N evaluated — N matched". Nothing
  // was evaluated: _fmtDetect short-circuits to the forced spec before any
  // recognizer runs. The panel was describing work that did not happen.
  const details = sandbox._t.ppDetectDetails;
  const strip = rows => rows.map(d => String(d.html).replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').trim());
  const winner = { type: 'ISO', label: 'ISO 8583 BIC', color: '#e6a817' };

  const forced = strip(details([{ winner, forced: true, trace: [{ label: 'ISO 8583 BIC', passed: true, forced: true }] }], 'message'));
  assert.ok(/forced by class override/i.test(forced[0]), `forced header, got: ${forced[0]}`);
  assert.ok(/not evaluated/i.test(forced[0]), 'the forced header must say recognizers did not run');
  assert.ok(!/evaluated —/.test(forced[0]), 'it must not read as a normal evaluation');
  assert.ok(/Forced as/.test(forced[1]), `forced verb, got: ${forced[1]}`);

  // The ordinary path is untouched — the wording only changes when forced.
  const normal = strip(details([{ winner, trace: [] }], 'message'));
  assert.ok(/evaluated/.test(normal[0]) && /matched/.test(normal[0]), `normal header, got: ${normal[0]}`);
  assert.ok(/Matched as/.test(normal[1]), `normal verb, got: ${normal[1]}`);
});

test('[REGRESSION] a record parse says the class override is on, and stops claiming a match', () => {
  // Two halves of one gap. v1.20.3.2 gave the PASTE flow an amber "class
  // override" step and taught the summary not to describe work that did not
  // happen; the RECORD flow got neither, and nothing noticed because the test
  // for it drove _ppDetectDetails directly. Armed, a record parse printed
  // "1 record evaluated — 1 matched" for a run where _fmtDetect short-circuited
  // before any recognizer ran. Reported 2026-08-25.
  //
  // Asserted at the source: _parseProgressDismiss empties _ppSteps when the run
  // ends, so nothing survives the flow to be read afterwards, and the steps are
  // pushed by a top-level function the sandbox cannot intercept.
  const rec = psFnSource('doParseNetardLog');

  // 1 — the amber step, ahead of the detection step it qualifies.
  const ovIdx  = rec.indexOf('Class override —');
  const detIdx = rec.indexOf("_parseProgressStep('Detecting record types')");
  assert.ok(ovIdx >= 0, 'the record flow never announces an armed class override');
  assert.ok(detIdx >= 0 && ovIdx < detIdx,
    'the override must be announced BEFORE detection is claimed');
  assert.ok(/S\.specOverride && S\.specOverride\.label/.test(rec), 'it must read the armed label');
  assert.ok(/'#e6a817', '#e6a817'/.test(rec.slice(ovIdx, detIdx)), 'the same amber both overrides use');
  assert.ok(/Recognizers — not evaluated/.test(rec.slice(ovIdx, detIdx)),
    'the step must say recognizers did not run');
  // The wording is NOT the DDL override's: that one also skips the parse-spec
  // and reads straight off the DDL, and overstating what was skipped is its own
  // bug. v1.20.3.2 pinned that distinction; it holds here too.
  const step = rec.slice(ovIdx, detIdx);
  assert.ok(!/Manual override mode/.test(step), 'a class override is not a manual DDL override');
  assert.ok(!/Parse-specs/i.test(step), 'the forced class STILL runs its parse-spec');

  // 2 — the summary. _fmtDetectTrace marks the RESULT forced; this flow pushed
  // only .trace, so _ppDetectDetails saw an ordinary passing trace and the
  // forced branch was never reached from here.
  assert.ok(/_detectTraces\.push\(\{[^}]*forced: !!_pd\.det\.forced/.test(rec.replace(/\n\s*/g, ' ')),
    'the record trace drops `forced`, so the summary reports a short-circuit as a match');
});

test('an armed entity override is visible in the list that still exists', () => {
  // Was: "shows in Settings, not only in the editor" — the Class Editor marked
  // it and Settings → Data Detection did not, so the same fact was visible in
  // one list and invisible in the other. Settings no longer carries a second
  // list (the Class Editor is its own page now), so the rule the original test
  // protected is the surviving half: an armed override you cannot see is the
  // defect, and the Entities list is where it has to be seen.
  assert.ok(!/renderDetectSpecsList/.test(APP_SRC),
    'the Settings list is back — then it must mark the override too');
  const list = psFnSource('_meRenderSpecList');
  assert.ok(/isSpecOverride\(/.test(list),
    'the Entities list must consult isSpecOverride, or an armed override is invisible');
  assert.ok(/me-item-forced/.test(list), 'the armed row gets no marking');
  const css = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/\.me-item\.me-item-forced\{/.test(css), 'the armed row needs its own treatment');
  // Colour is not the only carrier: the ▶ says it too.
  assert.ok(/\.me-item\.me-item-forced \.me-item-name::after\{content:'▶'/.test(css),
    'the armed row is marked by colour alone');
  const toggle = /function toggleSpecOverride\(idx\)\s*\{([\s\S]*?)\n\}/.exec(APP_SRC);
  assert.ok(toggle, 'toggleSpecOverride not found');
  assert.ok(/_meRenderSidebar\(\)/.test(toggle[1]),
    'toggling the override must refresh the list it is shown in');
});

test('the parse overlay announces an armed entity override', () => {
  // The DDL override prints an amber "Manual override mode" step. The entity
  // override printed nothing and the run looked like a normal detection.
  assert.ok(/Entity override — \$\{_armedSpec\}/.test(APP_SRC),
    'the parse flow must emit an override step when S.specOverride is armed');
  // Wording matters: the DDL override also skips the parse-spec, this one does
  // not — the forced entity's parse-spec and bindings still run. A notice that
  // overstates what was skipped is its own bug.
  const step = /Entity override — \$\{_armedSpec\}`,\s*'([^']*)'/.exec(APP_SRC);
  assert.ok(step, 'override step sub-label not found');
  assert.ok(!/Parse-specs/i.test(step[1]),
    `an entity override does not skip parse-specs — got: ${step[1]}`);
  assert.ok(/Recognizers/i.test(step[1]), `it does skip recognizers — got: ${step[1]}`);
});

// ── Import identity: the bug that ate two messages out of three ─────────────
console.log('\nimport — a bundle must arrive intact');

test('spec identity is the type code AND the label together', () => {
  // Neither field identifies an entity on its own. `name` is the badge's type
  // code and is shared — the shipped defaults carry three called ISO and three
  // called B24 — so keying on it collapsed three incoming ISO messages onto one
  // slot. The label alone was the first fix; the rule is the PAIR, so changing
  // either field makes it a different entity.
  const specKey = sandbox._t.specKey;
  const std = { name: 'ISO', label: 'ISO 8583 Standard' };
  const bic = { name: 'ISO', label: 'ISO 8583 BIC' };
  assert.notStrictEqual(specKey(std), specKey(bic),
    'same type code, different label — different entities');
  assert.notStrictEqual(specKey({ name: 'ISO', label: 'X' }), specKey({ name: 'I2', label: 'X' }),
    'same label, different type code — different entities');
  assert.strictEqual(specKey({ name: 'ISO', label: 'X' }), specKey({ name: 'ISO', label: 'X' }),
    'same pair — one entity');

  // Case and padding are noise: a near-miss that imports as "new" leaves the
  // user reconciling a duplicate by hand, which is the other half of the bug.
  assert.strictEqual(specKey({ name: 'iso', label: '  iso 8583 bic ' }), specKey(bic));

  // The separator must not be forgeable out of the fields themselves, or
  // "AB" + "C" and "A" + "BC" would key alike.
  assert.notStrictEqual(specKey({ name: 'AB', label: 'C' }), specKey({ name: 'A', label: 'BC' }));

  // No label falls back to the type, so an unlabelled spec still keys by
  // something rather than by the separator alone.
  assert.strictEqual(specKey({ name: 'MYMSG' }), specKey({ name: 'MYMSG', label: 'MYMSG' }));
});

test('adding entities never seeds a duplicate identity', () => {
  // + New seeded every message as NEW / "New Message", so pressing it twice
  // produced two entities the app cannot tell apart. _meUniqueLabel walks the
  // label until the type+label pair is free.
  const src = fs.readFileSync('./source.html', 'utf8');
  for (const fn of ['_meAddMsg', '_meAddOther', '_meAddFile']) {
    const m = new RegExp('function ' + fn + '\\(\\)\\s*\\{([\\s\\S]*?)\\n\\}').exec(src);
    assert.ok(m, fn + ' not found');
    assert.ok(/_meUniqueLabel\(/.test(m[1]),
      fn + ' must seed a label that is not already taken');
  }
});

test('the default specs really do collide on name but not on label', () => {
  // The premise of the test above, checked against the shipped data rather than
  // assumed — if the defaults ever stopped colliding, the test would go quietly
  // vacuous and stop guarding anything.
  const specKey = sandbox._t.specKey;
  const defaults = sandbox._t.fmtDefaultSpecs();
  assert.ok(Array.isArray(defaults) && defaults.length, 'defaults load');
  const names  = defaults.map(s => String(s.name || '').toUpperCase());
  const labels = defaults.map(specKey);
  assert.ok(names.length !== new Set(names).size,
    'the defaults are expected to share type codes — that is why name cannot be the key');
  assert.strictEqual(labels.length, new Set(labels).size,
    'labels must stay unique across the defaults, or import has no safe key at all');
});

test('import merges on identity, and rebuilds the token map', () => {
  // Both halves of the reported bug, pinned at the source. confirmImport must
  // not key a Map on `name`, and it must re-run buildTokenMap: token IDs are
  // derived from the imported DDL text, so badges stay missing until it does.
  const fn = /function confirmImport\(\)\s*\{([\s\S]*?)\n\}/.exec(APP_SRC);
  assert.ok(fn, 'confirmImport not found');
  const body = fn[1];
  assert.ok(!/new Map\(currentSpecs\.map\(\(s, i\) => \[\(s\.name/.test(body),
    'confirmImport must not key specs by name — that collapses ISO/B24 onto one slot');
  assert.ok(/_specKey\(/.test(body),
    'confirmImport must merge on _specKey');
  assert.ok(/buildTokenMap\(\)/.test(body),
    'confirmImport must rebuild the token map, or imported token DDLs show no badge');
});

test('the tutorial card measures in whole pixels', () => {
  // Its width, padding and gap are integers, but the HEIGHT is text-derived, so
  // a unitless line-height leaks a fraction into it: 1.6 on a 12px font is
  // 19.2px, and rules with no line-height fall back to fractional font metrics.
  // The card measured 307.875 tall — three edges clean, the bottom on a half
  // pixel — and it was the last element still looking wrong after the app moved
  // to 1px. --sz-mono is always whole (10/12/14), so calc() off it stays whole.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'))
                 .replace(/\/\*[\s\S]*?\*\//g, '');
  for (const sel of ['.tut-progress', '.tut-title', '.tut-body', '.tut-skip']) {
    const m = new RegExp(sel.replace('.', '\\.') + '\\s*\\{([^}]*)\\}').exec(css);
    assert.ok(m, `${sel} rule found`);
    const lh = /line-height:\s*([^;]+)/.exec(m[1]);
    assert.ok(lh, `${sel} must declare a line-height, or it inherits a fractional font metric`);
    assert.ok(!/^\s*[\d.]+\s*$/.test(lh[1]),
      `${sel} must not use a unitless multiplier — got line-height: ${lh[1].trim()}`);
  }
});

test('a dialog outranks every surface that can raise one', () => {
  // .modal-overlay carries the prompt/confirm box, the export and DDL-doc
  // modals and the parse-progress box. At 25000 it sat UNDER .settings-overlay
  // (30000), so "Erase All Data" — a prompt raised from Settings — appeared over
  // the dimmed main page, read as disabled, and could not be clicked at all.
  // Neither the export nor the import opener closes Settings first, so the same
  // trap was waiting for them. A dialog has to outrank anything that opens it.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'))
                 .replace(/\/\*[\s\S]*?\*\//g, '');
  const zOf = sel => {
    const m = new RegExp(sel.replace(/[.#]/g, '\\$&') + '\\s*\\{([^}]*)\\}').exec(css);
    const z = m && /z-index:\s*(\d+)/.exec(m[1]);
    return z ? +z[1] : null;
  };
  const modal = zOf('.modal-overlay');
  const settings = zOf('.settings-overlay');
  const editor = zOf('.me-overlay');
  const toast = zOf('#toast');
  assert.ok(modal && settings && editor && toast, 'all four layers declare a z-index');
  assert.ok(modal > settings,
    `a dialog must sit above the settings drawer — modal ${modal} vs settings ${settings}`);
  assert.ok(modal > editor,
    `a dialog must sit above the Class Editor — modal ${modal} vs editor ${editor}`);
  assert.ok(toast > modal,
    `the toast must clear the dialog it reports on — toast ${toast} vs modal ${modal}`);
});

test('the amber collapsed ring stays on panel headers', () => {
  // .panel-toggle.is-collapsed:hover paints an inset amber ring, which reads as
  // "this panel is collapsed". The same button markup is reused in the config
  // dialogs, where is-collapsed means "this column is on" — and there the ring
  // is just a yellow outline nobody asked for.
  //
  // Every one of these selectors weighs three class-level components, so the
  // later rule wins only the properties it NAMES. .settings-row already reset
  // box-shadow for this reason; .audit-cfg-row did not, so the ring leaked into
  // the columns editor. Any future context that restyles the toggle must reset
  // it too, so the requirement is checked for all of them rather than by name.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'))
                 .replace(/\/\*[\s\S]*?\*\//g, '');
  const base = /(^|\n)\.panel-toggle\.is-collapsed:hover\s*\{([^}]*)\}/.exec(css);
  assert.ok(base && /box-shadow:\s*inset/.test(base[2]),
    'the panel header still needs its amber ring — that is the intended signal');

  const missing = [];
  for (const m of css.matchAll(/(^|\n)([^{}\n]*\s\.panel-toggle:hover)\s*\{([^}]*)\}/g)) {
    if (!/box-shadow:\s*none/.test(m[3])) missing.push(m[2].trim());
  }
  deepEq(missing, [],
    'a scoped .panel-toggle:hover must reset box-shadow or the amber ring leaks through');
});

test('an icon button centres its glyph inside its fixed width', () => {
  // .btn.btn-ico pins the width at 30px and zeroes the horizontal padding so ⚙
  // and ✕ — different advance widths — come out the same size. That only works
  // if the flex box also centres: without justify-content the glyph sits at
  // flex-start, measured 2px from the left edge and 22px from the right, about
  // 10px off centre in a box built to look square.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'));
  const m = /(^|\n)\.btn-ico\s*\{([^}]*)\}/.exec(css);
  assert.ok(m, '.btn-ico rule not found');
  const decls = m[2];
  assert.ok(/display:\s*inline-flex/.test(decls), '.btn-ico must be a flex box');
  assert.ok(/justify-content:\s*center/.test(decls),
    '.btn-ico fixes its width and drops its padding, so it must centre its glyph — ' +
    `got: ${decls.trim().slice(0, 120)}`);
});

test('controls border with --bw-ctl, containers with --bw', () => {
  // Two width tokens on purpose. The split used to be defensive — --bw-ctl was
  // 2px to hide a two-tone edge on 1px coloured borders — and that turned out
  // not to be a CSS problem at all: the machine seeing it drove a TV over HDMI
  // with a subsampled chroma format, which averages colour across neighbouring
  // pixels and erases a 1px coloured line while leaving luminance-only greys
  // intact. Proven by elimination on one button (border, box-shadow and outline
  // all wrong at 1px on a whole-pixel box at dpr 1) and fixed by a display
  // setting, not a stylesheet.
  //
  // So the split is now structural: containers vs controls, same value today.
  // The widths are deliberately NOT pinned to specific pixel counts here —
  // pinning 2px is what this test used to do, and it would have to be edited
  // every time the design moves. What must not rot is that every control goes
  // through one token and every container through the other.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'))
                 .replace(/\/\*[\s\S]*?\*\//g, '');
  assert.ok(/--bw:\s*\d+px/.test(css), '--bw is declared');
  assert.ok(/--bw-ctl:\s*\d+px/.test(css), '--bw-ctl is declared');
  const rule = sel => {
    const m = new RegExp('(?:^|\\n)' + sel.replace(/[.#]/g, '\\$&') + '\\s*\\{([^}]*)\\}').exec(css);
    return m && m[1];
  };
  const btn = rule('.btn');
  assert.ok(btn, '.btn rule found');
  assert.ok(/border:\s*var\(--bw-ctl\)/.test(btn), `.btn must use --bw-ctl, got: ${btn.trim().slice(0, 90)}`);
  const panel = rule('.panel');
  assert.ok(panel, '.panel rule found');
  assert.ok(/border:\s*var\(--bw\)/.test(panel), `.panel must use --bw, got: ${panel.trim().slice(0, 90)}`);

  // Badges take --bw-ctl too. They were tried at the hairline on the theory that
  // a pill's curved ends hide the split — the user checked every font size and
  // every one looked wrong, so the theory was dropped. In this layout 21 of 24
  // badge tops land on fractional pixels; in the prototype, whose 1px badges do
  // look right, 19 of 27 land on whole ones. Same border, different layout.
  // .badge itself carries no border — the colour variants do.
  const badge = rule('.badge-hex');
  assert.ok(badge, '.badge-hex rule found');
  assert.ok(/border:\s*var\(--bw-ctl\)\s/.test(badge),
    `.badge-hex must use --bw-ctl, got: ${badge.trim().slice(0, 90)}`);

  // Text inputs are controls too, and they were the gap: the export modal's
  // filter box and the Field Map filter both shipped at --bw while every button
  // beside them sat at --bw-ctl, so they drew the two-tone edge the token exists
  // to prevent. Checking .btn and .badge alone did not catch it, so every rule
  // that borders a visible input is swept here rather than named one by one.
  // Anything sized by its own text: controls, and the pill-shaped notices that
  // behave like them. #toast was the one that got away — a text-sized pill
  // centred with translateX(-50%), which puts its edges on half pixels whenever
  // the content width is odd, so it drew the two-tone edge more reliably than
  // any button. #tutorialCard was left on --bw at first on the grounds that a
  // fixed 300px box lands on whole pixels — the user overruled it: a card that
  // reads as a dialog should carry the same edge as one, and the rule is
  // "controls and anything that looks like one", not a pixel-geometry argument.
  //
  // Identified by BEHAVIOUR as well as by name. Name-matching alone missed
  // .me-sel, .me-rb, .me-vlg-len, .audit-sd-op and .audit-dt-copy button — all
  // real controls whose class names abbreviate past the words being looked for
  // ("sel" is not "select"). A rule that sets cursor:pointer or appearance:none
  // is a control whatever it happens to be called.
  const CONTROLish = /input|textarea|select|filter|search|toast|pill|chip/i;
  const behavesLikeControl = d => /cursor:\s*pointer/.test(d) || /appearance:\s*none/.test(d);
  const offenders = [];
  for (const m of css.matchAll(/(^|\n)([^{}\n]+)\{([^}]*)\}/g)) {
    const [, , selector, decls] = m;
    if (!CONTROLish.test(selector) && !behavesLikeControl(decls)) continue;
    // A transparent border paints nothing, so the artifact cannot appear there;
    // #fmtForceSelect uses one purely to reserve layout space.
    if (/border:\s*var\(--bw\)\s+solid\s+(?!transparent)/.test(decls)) {
      offenders.push(selector.trim());
    }
  }
  deepEq(offenders, [],
    'these controls border at the container hairline — text-sized boxes need --bw-ctl');
});

test('the density block is declared after both theme blocks', () => {
  // [data-theme] and [data-density] are both attribute selectors on <html>, so
  // they carry equal specificity and SOURCE ORDER breaks the tie. Declared
  // before the themes, `--shadow-card:none` in compact silently lost to the
  // theme's own value and compact kept its drop shadows — nothing errors, the
  // rule just never applies. Order is load-bearing, so it is pinned here.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'));
  const dark    = css.indexOf('[data-theme="dark"] {');
  const light   = css.indexOf('[data-theme="light"] {');
  const density = css.indexOf('[data-density="compact"] {');
  assert.ok(dark >= 0 && light >= 0 && density >= 0, 'all three blocks exist');
  assert.ok(density > dark && density > light,
    'the density block must come after both theme blocks, or its shape tokens lose the tie');
});

test('a font change places the ruler after CodeMirror re-measures, not before', () => {
  // The Line Width ruler is positioned from view.defaultCharacterWidth, which
  // CodeMirror caches and only refreshes during its own measure cycle. applyPrefs
  // changed --sz-mono and then called _lwUpdateDisplay() on the same tick, so the
  // marker was placed with the OLD font's character width: on a 75-column NETARD
  // log, medium -> large put it 90px (about 11 columns) short of the last column.
  //
  // The +/- stepper hid this for months — 1px per click kept the marker roughly
  // one small step behind — and the three-way toggle exposed it by jumping up to
  // 4px at once. The fix is ordering, not arithmetic, so it is pinned here.
  const src = fs.readFileSync('./source.html', 'utf8');
  const fn = /function applyPrefs\([^)]*\)\s*\{([\s\S]*?)\n\}/.exec(src);
  assert.ok(fn, 'applyPrefs not found');
  const body = fn[1];
  const calls = [...body.matchAll(/_lwUpdateDisplay\(\)/g)].map(m => m.index);
  assert.ok(calls.length > 0, 'applyPrefs must still place the ruler');
  for (const at of calls) {
    // Every placement must sit inside a requestMeasure callback, or fall on the
    // no-editor branch where there is no cached width to be stale.
    const before = body.slice(0, at);
    const guarded = /requestMeasure\(\{[^}]*write:\s*\(\)\s*=>\s*$/.test(before.trimEnd() + ' ')
      || /requestMeasure\(\{[\s\S]{0,120}$/.test(before);
    const elseBranch = /\}\s*else\s*\{\s*$/.test(before);
    assert.ok(guarded || elseBranch,
      'applyPrefs must not call _lwUpdateDisplay() synchronously — CodeMirror still ' +
      'reports the previous font\'s character width, so the ruler lands short');
  }
  assert.ok(/_msgInputCM\.requestMeasure\(/.test(body),
    'applyPrefs must defer the ruler through _msgInputCM.requestMeasure');
});

test('density moves shape and spacing only, never colour', () => {
  // A density that also shifted colours would be a second theme wearing another
  // name, and the two would drift: switching to compact would silently restyle
  // the palette. Keeping it to geometry is what lets theme × density compose.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'));
  const i = css.indexOf('[data-density="compact"] {');
  const body = css.slice(i, css.indexOf('\n}', i));
  // Fails closed: an unrecognised token counts as a colour until it is listed
  // here, so adding a colour to the density block cannot slip through by
  // simply not matching the pattern.
  const SHAPE = /^--(r-|sp-|row-|gap|bw|shadow-)|^--[a-z-]+-[hw]$/;
  const bad = (body.match(/^\s*--[a-z0-9-]+/gim) || [])
    .map(t => t.trim()).filter(t => !SHAPE.test(t.replace(/^--/, '--')));
  eq(bad.length, 0, `density must not set colour tokens: ${bad.join(', ')}`);
});

test('[REGRESSION] changing the format mode does not clear the active spec variant', () => {
  // Both control groups in the Parse Spec bar carry .me-ps-variants, so the
  // format toggle's selector matched the Binary / ASCII pair as well: pressing
  // Compact marked Compact ON and, in the same pass, turned the active VARIANT
  // off. The spec then looked like it had no variant selected until the next
  // re-render put it back. Reported 2026-08-22 — it predates the bar work.
  const fn = psFnSource('_mePsSetFmtMode');
  assert.ok(/querySelectorAll\('#me-ps-fmt /.test(fn),
    `the format toggle reaches outside its own group: ${fn}`);
  assert.ok(!/\.me-ps-variants \.me-ps-variant-tgl/.test(fn),
    'the broad selector is back — it matches the variant toggles too');
  // And the group it scopes to is the one the markup builds.
  const src = fs.readFileSync('./source.html', 'utf8');
  assert.ok(/id="me-ps-fmt"/.test(src), 'the format group has no id to scope to');
});

test('[REGRESSION] every class a querySelector looks for is one the markup emits', () => {
  // A restructure renamed .me-ps-toolbar to a .panel-bar and left
  // _mePsSetFmtMode still querying the old name, so Compact / Expanded stopped
  // showing which one was pressed. Nothing failed — the selector simply matched
  // nothing. Found by reading, which is not a method. Reported 2026-08-22.
  const src = fs.readFileSync('./source.html', 'utf8');
  // Class tokens named inside a querySelector / querySelectorAll literal.
  const wanted = new Set();
  for (const m of src.matchAll(/querySelector(?:All)?\(\s*'([^']+)'/g))
    for (const c of m[1].matchAll(/\.([a-z][a-z0-9_-]*)/gi)) wanted.add(c[1]);
  // A class exists if any markup writes it, or any code adds it to an element.
  const emitted = new Set();
  for (const m of src.matchAll(/class="([^"]*)"/g))
    for (const t of m[1].split(/[\s${}?:'"]+/)) if (t) emitted.add(t);
  for (const m of src.matchAll(/classList\.(?:add|toggle|remove|contains)\(\s*'([^']+)'/g))
    emitted.add(m[1]);
  for (const m of src.matchAll(/className\s*=\s*'([^']*)'/g))
    for (const t of m[1].split(/\s+/)) if (t) emitted.add(t);
  // A class is often built as a fragment — `isGroup ? 'me-fm-grp' : ''`, or
  // `' tree-sel'` concatenated into a class attribute. Those are emitted too.
  for (const m of src.matchAll(/'\s*([a-z][a-z0-9_-]*)\s*'/gi)) emitted.add(m[1]);
  // CodeMirror puts its own classes on its own DOM; nothing here writes them.
  const dead = [...wanted].filter(c => !emitted.has(c) && !/^cm-/.test(c)).sort();
  deepEq(dead, [], 'querySelector looks for classes nothing ever puts on an element');
});

test('[REGRESSION] a help example can be selected — the app defaults to unselectable', () => {
  // `body { user-select: none }` covers the whole app, and every surface meant to
  // be READ opts back in. The example cards never did, so the only way to take
  // anything out of one was the copy button — which takes the whole example, when
  // most of the time a few lines is what is wanted. Reported 2026-08-22.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'));
  const rule = sel => {
    const i = css.indexOf(sel + '{');
    assert.ok(i >= 0, `${sel} is gone`);
    return css.slice(i, css.indexOf('}', i));
  };
  assert.ok(/user-select:\s*text/.test(rule('.me-ps-help-ex')),
    'the example card opts into selectable text');
  assert.ok(/user-select:\s*none/.test(rule('.me-ps-help-copy')),
    'and the copy button opts out — it sits INSIDE the snippet, so a drag across '
    + 'the block would otherwise carry its glyph into the clipboard');
  // The card is the unit, not the snippet: the payload bytes and the result rows
  // are as worth copying as the spec, and they are siblings inside it.
  assert.ok(/class="me-ps-help-ex"[\s\S]{0,600}me-ps-ex-bytes/.test(src),
    'the payload bytes really do live inside the card the rule covers');
});

test('[REGRESSION] no component paints a background in translucent white', () => {
  // A translucent WHITE lightens whatever is behind it, so it means the opposite
  // thing in the light theme — the reason six strips of controls and a progress
  // track read wrong there for months. The rule existed only in a comment beside
  // the one bar that had been converted, so nothing stopped the other six.
  // Reported 2026-08-19.
  //
  // Scrims are exempt and stay rgba(0,0,0,…): an overlay is meant to DARKEN the
  // page in both themes, which is the one case where a fixed colour is right.
  const src = fs.readFileSync('./source.html', 'utf8');
  const css = src.slice(src.indexOf('<style>'), src.indexOf('</style>'));
  // The token blocks are where a literal belongs — that is what defining a
  // theme means. Everything outside them has to go through a token.
  let body = '', last = 0;
  for (const m of css.matchAll(/(?:^|\n)\s*(?::root[^{\n]*|\[data-theme[^{\n]*)\{/g)) {
    body += css.slice(last, m.index);
    last = css.indexOf('\n}', m.index) + 2;
  }
  body += css.slice(last);
  const bad = (body.match(/[^;{}\n]*background[^;{}\n]*rgba\(\s*255,\s*255,\s*255[^)]*\)/g) || [])
    .map(s => s.trim());
  eq(bad.length, 0,
    `a background painted in translucent white inverts in the light theme: ${bad.join(' | ')}`);
  // There is now ONE rule for a bar, so the token is read once...
  const shared = (css.match(/\.panel-bar \{[^}]*\}/) || [''])[0];
  assert.ok(/background:\s*var\(--surface-subhead\)/.test(shared),
    'the shared bar does not take its surface from the token');
  // ...and every bar in the app has to actually BE one, or it silently drops
  // out of the primitive and grows its own look again — which is exactly how
  // six copies came to exist.
  for (const id of ['msgCfgBar', 'rawCfgBar', 'resCfgControls', 'recMetaRow', 'auditCfgBar', 'me-test-cfg']) {
    const tag = (html.match(new RegExp('<div[^>]*id="' + id + '"[^>]*>')) || [''])[0];
    assert.ok(/class="[^"]*\bpanel-bar\b/.test(tag),
      `#${id} is not wired to .panel-bar — it will drift: ${tag}`);
  }
});

test('the accent is written to one element, not two', () => {
  // The double-write was a symptom, not a fix. Once no theme block redefines
  // --accent on a descendant, one write to <html> reaches everything. If this
  // regrows a loop over [documentElement, body], the specificity bug is back.
  const src = fs.readFileSync('./source.html', 'utf8');
  // Renamed from _eggSetAccent when the accent stopped being an easter egg and
  // became a setting; the invariant it guards is unchanged.
  const fn = /function _applyAccent\([^)]*\)\s*\{([\s\S]*?)\n\}/.exec(src);
  assert.ok(fn, '_applyAccent not found');
  assert.ok(!/document\.body/.test(fn[1]),
    '_applyAccent must not touch document.body — write only to <html>');
});

// ── A help panel nothing can open is a help panel that does not exist ────────
// _meFmToggleHelp was defined, correct, and referenced by nothing: the "?" button
// in the Overrides toolbar had been lost, so the column reference was
// unreachable. The function stayed green in every test because tests call
// functions directly — nothing checked that a user can.
console.log('\nhelp panels — every toggle has a control that calls it');

test('every help toggle is wired to a button in the markup', () => {
  // Both declaration forms: several of these are one-line consts now that the
  // panels share an engine, and matching only `function` quietly stopped
  // checking them.
  const toggles = [...APP_SRC.matchAll(
    /^(?:function|const) (_me\w*Toggle\w*Help|_me\w*Help\w*Toggle)\s*[(=]/gm)].map(m => m[1]);
  assert.ok(toggles.length >= 5, `expected the help toggles, found ${toggles.length}: ${toggles}`);
  const orphans = toggles.filter(fn => !new RegExp(`onclick="${fn}\\(`).test(html));
  deepEq(orphans, [],
    'defined but nothing calls them — the control that opened the panel is gone');
});

test('help section toggles are buttons, not clickable divs', () => {
  // They were <div onclick>, which no keyboard can reach — the help sections
  // were mouse-only. As <button> they are focusable and activate on Enter or
  // Space for free. This also puts them inside the control border rule, which
  // is how the 1px indicator was spotted in the first place.
  const divToggles = [...html.matchAll(/<div[^>]*class="[^"]*h-sub-toggle[^"]*"/g)];
  eq(divToggles.length, 0, `${divToggles.length} help toggles are still <div onclick>`);
  const btnToggles = [...html.matchAll(/<button[^>]*class="[^"]*h-sub-toggle[^"]*"/g)];
  assert.ok(btnToggles.length >= 10,
    `expected the help toggles as buttons, found ${btnToggles.length}`);
  // A button inside a form-less page defaults to type=submit; without this they
  // would be fine here but wrong the moment one ends up inside a <form>.
  for (const m of btnToggles)
    assert.ok(/type="button"/.test(m[0]), `missing type="button": ${m[0].slice(0, 70)}`);
});

test('the Overrides column reference has its "?" button', () => {
  // Named specifically, because this is the one that went missing and the
  // generic check above would pass again the moment someone deletes the
  // function along with the button.
  assert.ok(/id="me-fm-help-btn"[^>]*onclick="_meFmToggleHelp\(\)"/.test(html),
    'the ? button is in the Overrides toolbar');
  assert.ok(/(?:function|const) _meFmToggleHelp\s*[(=]/.test(APP_SRC),
    'and the function it calls exists');
  // It sits with the other toolbar buttons, matching the two ? buttons elsewhere.
  const tb = html.slice(html.indexOf('me-fm-toolbar">'),
                        html.indexOf('</div>', html.indexOf('me-fm-cols-dlg')));
  assert.ok(/me-fm-help-btn/.test(tb), 'inside the Field Map toolbar');
  assert.ok(/class="btn"[^>]*id="me-fm-help-btn"/.test(html),
    'and carries the same classes as its siblings');
});

// ── The licence notice has to survive the build ──────────────────────────────
// The obfuscator runs with compact:true and strips every comment in the script
// block, so a banner written in the JS would vanish from the file people
// actually receive — and AGPL §13 is only satisfied by what the served app says.
console.log('\nlicensing — the notice reaches the built file');

test('the copyright banner is in the built index.html, not just the source', () => {
  const built = fs.readFileSync('./index.html', 'utf8');
  for (const needle of ['Copyright (C) 2026 Gatunox',
                        'GNU Affero General Public License',
                        'https://github.com/Gatunox/ddl-parser']) {
    assert.ok(built.includes(needle), `missing from index.html: ${needle}`);
    assert.ok(html.includes(needle),  `missing from source.html: ${needle}`);
  }
});

test('the banner sits outside the script block, where comments survive', () => {
  // If it ever moves inside, it still passes a naive "is it in source.html"
  // check and silently disappears from the build.
  const i = html.indexOf('Copyright (C) 2026 Gatunox');
  const scriptAt = html.indexOf('<script id="app">');
  assert.ok(i >= 0 && scriptAt >= 0, 'both markers found');
  assert.ok(i < scriptAt, 'the notice precedes the script the obfuscator rewrites');
  assert.ok(!APP_SRC.includes('Copyright (C) 2026 Gatunox'),
    'and it is not inside the script, where compact:true would strip it');
});

test('AGPL §13: the running app offers its users the source', () => {
  // The clause that makes AGPL work for something served over a network. The
  // FSF's own guidance is a source link in the interface; this is that link.
  const built = fs.readFileSync('./index.html', 'utf8');
  assert.ok(/href="https:\/\/github\.com\/Gatunox\/ddl-parser"/.test(built),
    'a source link is present in the served UI');
  assert.ok(/agpl-3\.0\.html/.test(built), 'and it names the licence it is under');
});

test('links in the settings drawer are styled, not left to the browser', () => {
  // The licence section introduced the drawer's first <a> elements. Unstyled,
  // they came out as the browser default #0000EE — measured 1.84:1 against the
  // panel, which is unreadable, and a blue this app uses nowhere else.
  const rule = html.match(/\.settings-drawer a\s*\{([^}]*)\}/);
  assert.ok(rule, 'the drawer styles its links');
  assert.ok(/color:\s*var\(--accent\)/.test(rule[1]),
    `and uses the palette, so both themes follow: ${rule[1].trim()}`);
  // Colour alone should not be the only affordance.
  assert.ok(/text-decoration:\s*underline/.test(rule[1]), 'and underlines them');
});

test('LICENSE is the verbatim AGPL-3.0, and package.json agrees', () => {
  const lic = fs.readFileSync('./LICENSE', 'utf8');
  assert.ok(/GNU AFFERO GENERAL PUBLIC LICENSE/.test(lic), 'LICENSE is the AGPL');
  assert.ok(/Version 3, 19 November 2007/.test(lic), 'version 3');
  // §13 is the difference between AGPL and GPL — if LICENSE were swapped for
  // the plain GPL, everything above still passes and the network clause is gone.
  assert.ok(/13\. Remote Network Interaction/.test(lic),
    'and it carries the remote-network-interaction clause, which plain GPL does not');
  const pkg = JSON.parse(fs.readFileSync('./package.json', 'utf8'));
  eq(pkg.license, 'AGPL-3.0-or-later', 'package.json declares the same licence');
  eq(pkg.author, 'Gatunox', 'and the same holder');
});

// ── APP_VERSION keeps up with the commits ────────────────────────────────────
// Three commits in a row (v1.11.0.0, v1.11.0.1, v1.12.0.0) shipped with
// APP_VERSION still reading 1.10.1.0, so the running app under-reported itself
// and the user could not tell whether their copy had the fix. Nothing in the
// suite noticed, because the version is a string no test read. Now the last
// commit's own subject line is the witness: whatever version it claims, the
// source must carry at least that.
console.log('\nrelease — APP_VERSION matches what the last commit claimed');

test('APP_VERSION is not behind the version in HEAD\'s subject line', () => {
  const src = fs.readFileSync('./source.html', 'utf8');
  const m   = src.match(/const APP_VERSION\s*=\s*'([0-9.]+)'/);
  assert.ok(m, 'APP_VERSION not found in source.html');

  let subject;
  try {
    subject = require('child_process')
      .execSync('git log -1 --format=%s', { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch { return; }                       // no git here — nothing to check against

  const claimed = subject.match(/\(v([0-9]+(?:\.[0-9]+){3})\)/);
  if (!claimed) return;                     // a commit that names no version makes no claim

  const num = v => v.split('.').map(Number);
  const [a, b] = [num(m[1]), num(claimed[1])];
  const cmp = a.reduce((r, n, i) => r !== 0 ? r : n - b[i], 0);
  assert.ok(cmp >= 0,
    `APP_VERSION is ${m[1]} but the last commit shipped as ${claimed[1]} — bump it in source.html and rebuild`);
});

// ── Summary ───────────────────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(50)}`);
if (failed === 0) {
  console.log(`All ${passed} tests passed.`);
} else {
  console.log(`${passed} passed, ${failed} FAILED.`);
  process.exit(1);
}
